/* Kelas VIII — Semester 1 — Asmaul Husna: al-Waliy, al-Hamid, asy-Syakur, al-Aliyy — 50 soal */
window.BSRegister({
'id':'k8-asmaul-husna-3','grade':8,'semester':1,'order':7,
'title':'Asmaul Husna (al-Waliy, al-Hamid, asy-Syakur, al-Aliyy)',
'desc':'Makna empat Asmaul Husna yaitu al-Waliy, al-Hamid, asy-Syakur, dan al-Aliyy beserta dalilnya, bukti pengamalannya dalam kehidupan sehari-hari, serta hikmah meneladani sifat-sifat tersebut bagi akhlak seorang muslim.',
'kd':'Menganalisis makna Asmaul Husna al-Waliy, al-Hamid, asy-Syakur dan al-Aliyy beserta dalilnya, dan menampilkan perilaku yang mencerminkan penghayatan terhadap keempat Asmaul Husna tersebut dalam kehidupan sehari-hari.',
'questions':[{level:'HOTS',indicator:'Menentukan makna al-Waliy',text:'Makna Asmaul Husna al-Waliy yang paling tepat adalah ...',options:['Zat yang menguasai seluruh makhluk sehingga tidak ada yang dapat melawan kekuasaan-Nya','Zat yang memiliki kedudukan paling tinggi sehingga tidak ada yang setara dengan-Nya','Zat yang memberi balasan berlipat atas amal yang sedikit sehingga amal hamba tidak sia-sia','pelindung dan penolong hamba beriman sehingga tidak memerlukan selain Dia'],answer:3,explanation:'Kata al-Waliy berasal dari akar kata yang mengandung makna kedekatan, sehingga al-Waliy berarti yang dekat dengan hamba-Nya dan menjadi pelindung serta penolong mereka. Q.S. al-Baqarah [2]: 257 menyebut bahwa Allah adalah pelindung orang-orang yang beriman yang mengeluarkan mereka dari kegelapan kepada cahaya, sedangkan orang-orang kafir pelindungnya adalah tagut. Q.S. asy-Syura [42]: 28 menyebut bahwa Dialah yang menurunkan hujan setelah mereka berputus asa dan menyebarkan rahmat-Nya dan Dialah Sang Pelindung lagi Maha Terpuji. Q.S. al-Ankabut [29]: 22 menyebut bahwa orang kafir tidak akan dapat melepaskan diri dari azab Allah di bumi dan tidak ada pelindung maupun penolong bagi mereka selain Allah. Hadis juga menganjurkan memohon perlindungan kepada Allah dalam setiap keadaan. Adapun makna menguasai merupakan makna al-Qahhar atau al-Malik, makna kedudukan paling tinggi merupakan makna al-Aliyy, dan makna memberi balasan berlipat merupakan makna asy-Syakur.'},
{level:'HOTS',indicator:'Menganalisis dalil tentang al-Waliy',text:'Q.S. al-Baqarah [2]: 257 menyebut bahwa Allah adalah pelindung orang-orang yang beriman. Analisis yang paling tepat terhadap kandungan ayat tersebut dalam kaitannya dengan al-Waliy adalah ...',options:['ayat itu menunjukkan bahwa tagut merupakan pelindung yang nyata bagi orang kafir di akhirat','ayat itu menunjukkan bahwa orang beriman tidak memerlukan usaha karena Allah telah melindunginya','ayat itu menunjukkan bahwa perlindungan Allah hanya berlaku bagi orang beriman yang tidak pernah berbuat salah','perlindungan Allah berupa petunjuk dari kegelapan menuju cahaya'],answer:3,explanation:'Q.S. al-Baqarah [2]: 257 berbunyi Allah adalah pelindung orang-orang yang beriman yang mengeluarkan mereka dari kegelapan kepada cahaya, dan orang-orang yang kafir pelindung-pelindungnya adalah tagut yang mengeluarkan mereka dari cahaya kepada kegelapan, mereka itulah penghuni neraka dan mereka kekal di dalamnya. Q.S. asy-Syura [42]: 9 menyebut bahwa orang yang menjadikan pelindung selain Allah maka Allah merupakan pengawas atas seluruh perbuatan mereka. Q.S. al-Ankabut [29]: 22 menyebut bahwa orang kafir tidak akan dapat melepaskan diri dari azab Allah di bumi dan tidak ada pelindung maupun penolong bagi mereka selain Allah. Q.S. al-Jatsiyah [45]: 19 menyebut bahwa mereka tidak akan berguna sedikit pun bagi manusia terhadap azab Allah. Hadis juga menyebut bahwa barangsiapa bertawakal kepada Allah maka Dia mencukupinya. Adapun ayat itu tidak menghapus keperluan berusaha karena tawakal dalam Islam selalu disertai ikhtiar, dan perlindungan Allah tetap berlaku bagi orang beriman yang berbuat salah lalu bertaubat.'},
{level:'HOTS',indicator:'Menentukan perilaku yang mencerminkan penghayatan al-Waliy',text:'Perilaku yang paling tepat sebagai penghayatan terhadap Asmaul Husna al-Waliy adalah ...',options:['menjadikan Allah pelindung utama dan tidak menggantungkan pada makhluk','mencari pelindung dari orang yang berkuasa agar memperoleh keamanan dalam kehidupan','tidak mencari perlindungan dari siapa pun karena mencari perlindungan menunjukkan kelemahan iman','mencari perlindungan dari orang yang kuat selama tidak melanggar ketentuan agama secara nyata'],answer:0,explanation:'Q.S. al-Falaq [113]: 1-2 memerintahkan berlindung kepada Tuhan yang menguasai waktu subuh dari kejahatan makhluk-Nya. Q.S. an-Nas [114]: 1-3 memerintahkan berlindung kepada Tuhan manusia, Raja manusia, dan Sembahan manusia. Q.S. at-Taubah [9]: 51 mengajarkan ucapan cukuplah Allah bagi kami dan Dia adalah sebaik-baik pelindung. Hadis menyebut bahwa apabila seseorang meminta perlindungan kepada orang lain maka hendaklah orang yang dimintai perlindungan itu memberinya selama tidak untuk perkara yang dilarang. Hadis juga menganjurkan menolong orang yang dizalimi dan orang yang menzalimi dengan cara mencegahnya. Q.S. al-Maidah [5]: 2 memerintahkan tolong-menolong dalam kebaikan dan takwa. Hadis juga menyebut bahwa barangsiapa bertawakal kepada Allah maka Dia mencukupinya. Adapun tidak mencari perlindungan dari siapa pun bukan penghayatan yang tepat karena Islam mengajarkan berlindung kepada Allah dan juga membolehkan meminta bantuan kepada sesama dalam perkara yang dibenarkan, dan mencari perlindungan dari pihak yang berkuasa untuk melanggar ketentuan agama bukan penghayatan al-Waliy melainkan bentuk ketergantungan pada makhluk.'},
{level:'HOTS',indicator:'Menentukan makna al-Hamid',text:'Makna Asmaul Husna al-Hamid yang paling tepat adalah ...',options:['Zat yang melindungi hamba-Nya dari bahaya sehingga hamba merasa aman dalam seluruh keadaan','Zat yang memuji hamba-hamba-Nya yang beriman sehingga amal mereka diterima','terpuji dalam seluruh keadaan karena kesempurnaan zat dan sifat-Nya','Zat yang membalas amal hamba dengan balasan yang berlipat sehingga amal yang sedikit menjadi banyak pahalanya'],answer:2,explanation:'Kata al-Hamid berasal dari akar kata hamd yang berarti pujian disertai penghormatan dan kecintaan, sehingga al-Hamid berarti Zat yang terpuji secara sempurna dan berhak atas segala pujian. Q.S. al-Hajj [22]: 64 menyebut bahwa milik-Nya apa yang di langit dan di bumi dan sesungguhnya Allah benar-benar Maha Kaya lagi Maha Terpuji. Q.S. Luqman [31]: 26 menyebut bahwa milik Allah apa yang di langit dan di bumi dan sesungguhnya Allah Dialah Yang Maha Kaya lagi Maha Terpuji. Q.S. Saba [34]: 1 menyebut bahwa milik Allah apa yang di langit dan di bumi dan bagi-Nya segala puji di akhirat. Q.S. al-Fatihah [1]: 2 dibuka dengan segala puji bagi Allah Tuhan seluruh alam, sehingga setiap salat dimulai dengan pujian kepada-Nya. Hadis juga menyebut bahwa Rasulullah membaca hamdalah dalam setiap khutbah dan keadaan. Adapun makna memuji hamba bukan makna al-Hamid karena al-Hamid berarti yang terpuji bukan yang memuji, makna membalas berlipat merupakan makna asy-Syakur, dan makna melindungi merupakan makna al-Waliy atau al-Hafiz.'},
{level:'HOTS',indicator:'Menganalisis hubungan al-Hamid dengan perintah memuji Allah',text:'Allah bernama al-Hamid dan manusia diperintahkan memuji-Nya dalam setiap keadaan. Analisis yang paling tepat terhadap hubungan keduanya adalah ...',options:['hubungan itu menunjukkan bahwa pujian manusia menambah kemuliaan Allah','hubungan itu menunjukkan bahwa Allah memerlukan pujian manusia sebagaimana manusia memerlukan pujian','hubungan itu menunjukkan bahwa pujian hanya dilakukan ketika memperoleh nikmat yang menyenangkan','pujian manusia tidak menambah kemuliaan Allah namun bermanfaat baginya'],answer:3,explanation:'Hadis qudsi menyebut bahwa Allah berfirman wahai hamba-hamba-Ku sesungguhnya kalian tidak akan mampu memberi manfaat kepada-Ku sehingga kalian tidak dapat memberi manfaat kepada-Ku dan kalian tidak akan mampu memberi mudarat kepada-Ku sehingga kalian tidak dapat memberi mudarat kepada-Ku. Q.S. az-Zumar [39]: 7 menyebut bahwa apabila bersyukur maka syukur itu untuk diri sendiri dan apabila kufur maka sesungguhnya Allah Maha Kaya lagi Maha Terpuji. Q.S. Ibrahim [14]: 8 menyebut bahwa apabila kufur maka sesungguhnya Allah Maha Kaya dari kalian dan Dia tidak meridai kekufuran bagi hamba-hamba-Nya. Hadis juga menyebut bahwa Rasulullah apabila memperoleh hal yang menyenangkan maka bersabda segala puji bagi Allah yang dengan nikmat-Nya sempurnalah kebaikan, dan apabila memperoleh hal yang tidak menyenangkan maka bersabda segala puji bagi Allah dalam setiap keadaan. Q.S. ar-Rum [30]: 18 menyebut pujian bagi Allah di waktu petang dan pagi. Hadis menyebut bahwa kalimat yang paling dicintai Allah ada empat yaitu subhanallah, alhamdulillah, la ilaha illallah, dan Allahu akbar.'},
{level:'HOTS',indicator:'Menentukan perilaku yang mencerminkan penghayatan al-Hamid',text:'Perilaku yang paling tepat sebagai penghayatan terhadap Asmaul Husna al-Hamid adalah ...',options:['memuji orang lain secara berlebihan agar mereka senang dan membalas pujian itu','memuji Allah ketika memperoleh nikmat yang besar saja karena nikmat kecil tidak memerlukan pujian','memuji Allah dengan lisan, hati, dan perbuatan dalam setiap keadaan','memuji Allah dengan lisan tanpa perlu mewujudkan pujian dalam perbuatan karena pujian lisan sudah cukup'],answer:2,explanation:'Hadis menyebut bahwa Rasulullah apabila memperoleh hal yang menyenangkan maka mengucapkan hamdalah karena nikmat yang menyempurnakan kebaikan dan apabila memperoleh hal yang tidak menyenangkan maka mengucapkan hamdalah dalam setiap keadaan. Q.S. al-Fatihah [1]: 2 menyebut segala puji bagi Allah Tuhan seluruh alam yang dibaca dalam setiap rakaat salat. Q.S. Ibrahim [14]: 7 menyebut bahwa apabila bersyukur maka Allah menambah nikmat. Hadis juga menyebut bahwa orang yang tidak bersyukur kepada manusia tidak bersyukur kepada Allah, sehingga memuji orang lain atas kebaikannya merupakan bagian dari syukur. Hadis melarang memuji secara berlebihan dan menyebut bahwa melempar tanah ke wajah orang yang memuji berlebihan merupakan sikap yang dianjurkan, sehingga pujian harus disampaikan secara benar. Q.S. an-Najm [53]: 32 melarang menyebut diri sendiri suci. Hadis qudsi juga menyebut bahwa Allah Maha Cukup dari sekutu sehingga amal yang dikerjakan untuk memperoleh pujian ditolak.'},
{level:'HOTS',indicator:'Menentukan makna asy-Syakur',text:'Makna Asmaul Husna asy-Syakur yang paling tepat adalah ...',options:['Zat yang mencatat seluruh amal hamba sehingga tidak ada amal yang terlewat','Zat yang memberi nikmat tanpa henti sehingga hamba tidak pernah kekurangan rezeki','membalas amal hamba dengan balasan berlipat walaupun amalnya sedikit','Zat yang mensyukuri hamba-Nya dengan memberi nikmat terlebih dahulu sebelum hamba itu bersyukur'],answer:2,explanation:'Kata asy-Syakur merupakan bentuk mubalaghah dari syakir yang berarti banyak membalas kebaikan, sehingga asy-Syakur berarti Zat yang membalas amal hamba dengan balasan yang jauh melampaui amal tersebut. Q.S. al-Baqarah [2]: 261 memberi perumpamaan orang yang menafkahkan hartanya di jalan Allah seperti satu biji yang menumbuhkan tujuh tangkai dan pada setiap tangkai terdapat seratus biji, serta menyebut bahwa Allah melipatgandakan bagi siapa yang dikehendaki-Nya. Q.S. Fathir [35]: 30 menyebut bahwa Allah akan menyempurnakan pahala mereka dan menambah bagi mereka dari karunia-Nya. Q.S. asy-Syura [42]: 23 menyebut kabar gembira bagi orang yang beriman dan beramal saleh bahwa Allah menambah karunia-Nya. Hadis qudsi menyebut bahwa barangsiapa datang dengan kebaikan maka baginya sepuluh kali lipatnya atau lebih, dan barangsiapa datang dengan keburukan maka balasan keburukan itu serupa atau diampuni. Hadis juga menyebut bahwa barangsiapa berniat kebaikan lalu tidak melaksanakannya maka dicatat satu kebaikan baginya. Adapun makna mencatat amal merupakan makna al-Hasib atau al-Muhsi, dan makna memberi nikmat tanpa henti merupakan makna ar-Razzaq atau al-Wahhab.'},
{level:'HOTS',indicator:'Menganalisis hubungan asy-Syakur dengan perintah bersyukur',text:'Allah bernama asy-Syakur dan manusia diperintahkan bersyukur atas nikmat-Nya. Analisis yang paling tepat terhadap hubungan keduanya adalah ...',options:['hubungan itu menunjukkan bahwa syukur hanya berlaku bagi nikmat yang besar bukan bagi nikmat yang kecil','hubungan itu menunjukkan bahwa syukur manusia merupakan bentuk membalas kebaikan Allah sehingga Allah berutang balasan','hubungan itu menunjukkan bahwa syukur manusia menyebabkan Allah membalas dengan tambahan nikmat sehingga syukur merupakan sebab tambahan','syukur Allah berupa balasan berlipat, syukur manusia berupa pengakuan'],answer:3,explanation:'Q.S. Ibrahim [14]: 7 berbunyi dan ingatlah ketika Tuhanmu memaklumkan sesungguhnya jika kamu bersyukur pasti Kami akan menambah nikmat kepadamu dan jika kamu mengingkari nikmat-Ku maka sesungguhnya azab-Ku sangat pedih. Q.S. al-Baqarah [2]: 152 memerintahkan mengingat Allah maka Allah akan mengingat kalian dan bersyukurlah kepada-Ku dan janganlah mengingkari nikmat-Ku. Q.S. Fathir [35]: 30 menyebut bahwa Allah akan menyempurnakan pahala mereka dan menambah bagi mereka dari karunia-Nya karena sesungguhnya Allah Maha Pengampun lagi Maha Mensyukuri. Hadis qudsi menyebut bahwa Allah berfirman Aku sesuai dengan prasangka hamba-Ku terhadap-Ku dan Aku bersamanya ketika ia mengingat-Ku. Hadis juga menyebut bahwa Allah Maha Pemurah dan menyukai orang yang pemurah. Q.S. an-Nahl [16]: 18 menyebut bahwa apabila menghitung nikmat Allah niscaya tidak mampu menghitungnya, sehingga syukur berlaku untuk nikmat yang kecil maupun yang besar. Hadis menyebut bahwa orang yang tidak bersyukur kepada manusia tidak bersyukur kepada Allah.'},
{level:'HOTS',indicator:'Menentukan perilaku yang mencerminkan penghayatan asy-Syakur',text:'Perilaku yang paling tepat sebagai penghayatan terhadap Asmaul Husna asy-Syakur adalah ...',options:['mengharapkan balasan dari orang lain atas kebaikan yang telah dilakukan agar kebaikannya tidak sia-sia','menunda amal hingga mampu beramal dalam jumlah besar agar balasannya lebih besar','beramal sebanyak mungkin karena balasan amal ditentukan oleh jumlah amal','beramal walaupun sedikit secara berkelanjutan dan tidak menyebut-nyebutnya'],answer:3,explanation:'Hadis menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Q.S. al-Zalzalah [99]: 7-8 menyebut bahwa barangsiapa mengerjakan kebaikan sebesar biji zarrah maka ia akan melihatnya dan barangsiapa mengerjakan keburukan sebesar biji zarrah maka ia akan melihatnya, sehingga amal kecil tidak boleh diremehkan. Hadis juga menyebut bahwa janganlah meremehkan kebaikan sedikit pun walaupun hanya bertemu saudaramu dengan wajah yang berseri. Hadis menyebut bahwa iman memiliki lebih dari tujuh puluh cabang yang terendah adalah menyingkirkan gangguan dari jalan. Q.S. al-Baqarah [2]: 264 melarang menghilangkan pahala sedekah dengan menyebut-nyebutnya dan menyakiti perasaan penerima. Hadis menganjurkan membalas kebaikan dengan kebaikan serupa dan menyebut bahwa orang yang tidak berterima kasih kepada manusia tidak bersyukur kepada Allah. Q.S. an-Nahl [16]: 126 menganjurkan membalas dengan balasan yang serupa dan menyebut bahwa bersabar lebih baik bagi orang yang sabar. Adapun menunda amal karena menunggu mampu beramal besar merupakan bentuk mengulur waktu yang dapat berakibat amal tidak terlaksana, dan mengharapkan balasan dari manusia bukan penghayatan asy-Syakur karena balasan yang diharapkan adalah dari Allah.'},
{level:'HOTS',indicator:'Menentukan makna al-Aliyy',text:'Makna Asmaul Husna al-Aliyy yang paling tepat adalah ...',options:['Zat yang berada di tempat yang tinggi di atas langit sehingga tidak terjangkau oleh makhluk','Zat yang mengangkat derajat hamba-hamba-Nya yang beriman sehingga mereka memperoleh kedudukan tinggi di sisi-Nya','Zat yang mengawasi seluruh perbuatan hamba dari tempat yang tinggi sehingga tidak ada yang tersembunyi dari-Nya','berkedudukan Maha Tinggi pada zat dan sifat bukan ketinggian tempat'],answer:3,explanation:'Kata al-Aliyy berasal dari akar kata yang mengandung makna ketinggian, sehingga al-Aliyy berarti Zat yang Maha Tinggi kedudukannya dan Maha Agung. Q.S. al-Baqarah [2]: 255 atau ayat Kursi menyebut bahwa Dia Maha Tinggi lagi Maha Besar. Q.S. asy-Syura [42]: 51 tidak menyebut al-Aliyy secara langsung tetapi menyebut kedudukan wahyu sebagai ruh dari perintah Allah. Q.S. Luqman [31]: 30 menyebut bahwa hal itu karena sesungguhnya Allah Dialah yang hak dan sesungguhnya apa yang mereka seru selain Allah adalah batil, dan sesungguhnya Allah Dialah Yang Maha Tinggi lagi Maha Besar. Q.S. al-Hajj [22]: 62 menyebut bahwa hal itu karena sesungguhnya Allah Dialah yang hak dan sesungguhnya apa yang mereka seru selain-Nya adalah batil dan sesungguhnya Allah Dialah Yang Maha Tinggi lagi Maha Besar. Q.S. asy-Syura [42]: 4 tidak menyebut secara langsung. Adapun makna mengangkat derajat hamba merupakan sebagian dari perbuatan Allah tetapi bukan makna utama al-Aliyy, makna mengawasi merupakan makna al-Bashir atau ar-Raqib, dan ketinggian tempat yang membatasi merupakan pemahaman yang tidak tepat karena Q.S. asy-Syura [42]: 11 menyebut bahwa tidak ada sesuatu pun yang serupa dengan Dia.'},
{level:'HOTS',indicator:'Menganalisis dalil tentang al-Aliyy',text:'Q.S. al-Baqarah [2]: 255 menyebut bahwa Allah Maha Tinggi lagi Maha Besar. Analisis yang paling tepat terhadap kandungan ayat tersebut dalam kaitannya dengan al-Aliyy adalah ...',options:['ayat itu menunjukkan bahwa kursi Allah merupakan tempat duduk Allah di langit','ketinggian Allah tidak ada bandingannya dan seluruh makhluk di bawah-Nya','ayat itu menunjukkan bahwa Allah berada di tempat yang tinggi sehingga doa harus disampaikan ke arah atas','ayat itu menunjukkan bahwa langit dan bumi merupakan bagian dari zat Allah sehingga keduanya besar'],answer:1,explanation:'Q.S. al-Baqarah [2]: 255 atau ayat Kursi berbunyi Allah tidak ada tuhan melainkan Dia Yang Hidup kekal lagi terus-menerus mengurus makhluk-Nya, tidak mengantuk dan tidak tidur, milik-Nya apa yang di langit dan di bumi, siapakah yang dapat memberi syafaat di sisi-Nya kecuali dengan izin-Nya, Dia mengetahui apa yang di hadapan mereka dan apa yang di belakang mereka sedangkan mereka tidak mengetahui sesuatu dari ilmu-Nya melainkan apa yang dikehendaki-Nya, kursi-Nya meliputi langit dan bumi dan Dia tidak merasa berat memelihara keduanya, dan Dia Maha Tinggi lagi Maha Besar. Q.S. asy-Syura [42]: 11 menyebut bahwa tidak ada sesuatu pun yang serupa dengan Dia dan Dialah Yang Maha Mendengar lagi Maha Melihat. Q.S. al-Ikhlas [112]: 4 menyebut bahwa tidak ada seorang pun yang setara dengan Dia. Q.S. Luqman [31]: 30 dan Q.S. al-Hajj [22]: 62 menyebut bahwa Allah Maha Tinggi lagi Maha Besar. Hadis qudsi menyebut bahwa kebesaran merupakan selendang Allah dan keperkasaan merupakan pakaian-Nya. Adapun arah mengangkat tangan ketika berdoa merupakan adab yang diajarkan dan bukan bukti bahwa Allah berada di tempat tertentu, dan kursi dalam ayat itu merupakan makhluk Allah yang besar bukan tempat duduk dalam pengertian manusia.'},
{level:'HOTS',indicator:'Menentukan perilaku yang mencerminkan penghayatan al-Aliyy',text:'Perilaku yang paling tepat sebagai penghayatan terhadap Asmaul Husna al-Aliyy adalah ...',options:['tidak tinggi hati atas kedudukan dan tidak tunduk pada kezaliman','berusaha memperoleh kedudukan yang tinggi di masyarakat agar dihormati oleh orang lain','menghormati orang yang memiliki kedudukan tinggi karena kedudukan itu merupakan tanda kemuliaan di sisi Allah','tidak mencari kedudukan sama sekali karena kedudukan selalu menimbulkan kesombongan'],answer:0,explanation:'Hadis qudsi menyebut bahwa kebesaran merupakan selendang Allah dan keperkasaan merupakan pakaian-Nya sehingga barangsiapa menyaingi-Nya dalam salah satu dari keduanya akan dimasukkan ke neraka. Hadis juga menyebut bahwa sombong adalah menolak kebenaran dan meremehkan manusia, dan bahwa tidak akan masuk surga orang yang di dalam hatinya terdapat kesombongan sebesar biji sawi. Q.S. al-Munafiqun [63]: 8 menyebut bahwa kemuliaan itu hanyalah bagi Allah, bagi Rasul-Nya, dan bagi orang-orang mukmin. Hadis menyebut bahwa tidak ada yang bersikap tawadu karena Allah melainkan Allah mengangkat derajatnya. Q.S. al-Hujurat [49]: 13 menegaskan bahwa yang paling mulia di sisi Allah adalah yang paling bertakwa. Hadis juga menyebut bahwa tidak ada ketaatan kepada makhluk dalam bermaksiat kepada Pencipta, sehingga tidak tunduk kepada pihak yang berkuasa untuk melakukan perbuatan yang dilarang merupakan wujud penghayatan bahwa kekuasaan makhluk berada di bawah kekuasaan Allah. Adapun tidak mencari kedudukan sama sekali bukan penghayatan yang tepat karena kedudukan dapat menjadi sarana memberi manfaat, dan menghormati kedudukan sebagai tanda kemuliaan di sisi Allah bukan ukuran yang benar.'},
{level:'HOTS',indicator:'Menganalisis keterkaitan keempat Asmaul Husna dalam satu rangkaian',text:'Al-Waliy, al-Hamid, asy-Syakur, dan al-Aliyy dipelajari dalam satu rangkaian Asmaul Husna. Analisis yang paling tepat terhadap keterkaitan keempatnya adalah ...',options:['al-Waliy dan al-Aliyy berkaitan sedangkan al-Hamid dan asy-Syakur merupakan nama yang berdiri sendiri','keempatnya hanya berkaitan dalam bentuk lafal karena seluruhnya merupakan sifat yang sama','keempatnya merupakan nama yang tidak berkaitan satu sama lain sehingga dapat dipelajari secara terpisah','pelindung terpuji yang membalas amal dan berkedudukan paling tinggi'],answer:3,explanation:'Q.S. asy-Syura [42]: 28 menggandengkan al-Waliy dengan al-Hamid dalam satu ayat yaitu Dialah yang menurunkan hujan setelah mereka berputus asa dan menyebarkan rahmat-Nya dan Dialah Sang Pelindung lagi Maha Terpuji. Q.S. Fathir [35]: 30 menggandengkan penyempurnaan pahala dan penambahan karunia dengan sifat Maha Pengampun lagi Maha Mensyukuri. Q.S. Luqman [31]: 30 dan Q.S. al-Hajj [22]: 62 menggandengkan sifat Maha Tinggi dengan sifat Maha Besar. Q.S. al-Baqarah [2]: 257 menyebut Allah sebagai pelindung orang beriman yang mengeluarkan mereka dari kegelapan kepada cahaya. Hadis qudsi menyebut bahwa kebesaran merupakan selendang Allah dan keperkasaan merupakan pakaian-Nya. Q.S. al-Fatihah [1]: 2 menyebut segala puji bagi Allah Tuhan seluruh alam. Hadis juga menyebut bahwa Allah Maha Pemurah dan menyukai orang yang pemurah, sehingga hamba didorong meneladani sifat-sifat itu dalam batas kemanusiaannya. Karena itu keempat nama itu membentuk rangkaian yang saling menguatkan keyakinan hamba terhadap penjagaan dan balasan dari Allah.'},
{level:'HOTS',indicator:'Menentukan dalil yang menggandengkan al-Waliy dengan al-Hamid',text:'Ayat yang menggandengkan nama al-Waliy dengan al-Hamid adalah ...',options:['Q.S. Luqman [31]: 30','Q.S. al-Baqarah [2]: 255','Q.S. asy-Syura [42]: 28','Q.S. Fathir [35]: 30'],answer:2,explanation:'Q.S. asy-Syura [42]: 28 berbunyi dan Dialah yang menurunkan hujan setelah mereka berputus asa dan menyebarkan rahmat-Nya dan Dialah Sang Pelindung lagi Maha Terpuji, sehingga ayat itu menggandengkan al-Waliy dengan al-Hamid. Adapun Q.S. al-Baqarah [2]: 255 atau ayat Kursi menggandengkan sifat Maha Tinggi dengan sifat Maha Besar, Q.S. Fathir [35]: 30 menyebut Allah Maha Pengampun lagi Maha Mensyukuri dalam konteks menyempurnakan pahala dan menambah karunia, dan Q.S. Luqman [31]: 30 menggandengkan sifat Maha Tinggi dengan sifat Maha Besar dalam konteks menegaskan bahwa Allah merupakan yang hak dan sesembahan selain-Nya merupakan batil. Hadis juga menganjurkan berdoa dengan menyebut nama-nama Allah yang indah sebagaimana Q.S. al-Araf [7]: 180. Karena itu ayat yang secara khusus menggandengkan al-Waliy dengan al-Hamid adalah Q.S. asy-Syura [42]: 28.'},
{level:'HOTS',indicator:'Menganalisis hikmah ditetapkannya nama al-Waliy bagi Allah',text:'Allah menetapkan nama al-Waliy bagi diri-Nya dan memerintahkan hamba-Nya menjadikan Dia sebagai pelindung. Analisis yang paling tepat terhadap hikmah penetapan tersebut adalah ...',options:['hati bergantung pada satu Zat sehingga tidak terpecah kepada banyak pihak','hikmahnya agar hamba tidak takut terhadap makhluk sehingga berani melakukan apa pun','hikmahnya karena nama al-Waliy merupakan nama Allah yang paling utama di antara seluruh Asmaul Husna','hikmahnya agar hamba tidak memerlukan bantuan dari sesama manusia'],answer:0,explanation:'Q.S. al-Baqarah [2]: 257 menyebut bahwa Allah adalah pelindung orang-orang yang beriman. Q.S. at-Taubah [9]: 51 mengajarkan ucapan cukuplah Allah bagi kami dan Dia adalah sebaik-baik pelindung. Q.S. asy-Syura [42]: 9 menyebut bahwa orang yang menjadikan pelindung selain Allah maka Allah merupakan pengawas atas seluruh perbuatan mereka. Hadis menyebut bahwa barangsiapa bertawakal kepada Allah maka Dia mencukupinya. Hadis juga menyebut bahwa Allah menolong hamba selama hamba menolong saudaranya, sehingga meneladani sifat pelindung dengan menolong sesama merupakan bagian dari penghayatan. Q.S. al-Maidah [5]: 2 memerintahkan tolong-menolong dalam kebaikan dan takwa. Hadis menganjurkan menolong orang yang dizalimi. Adapun nama al-Waliy bukan nama yang paling utama karena para ulama berbeda pendapat tentang nama yang paling agung dan seluruh Asmaul Husna merupakan nama yang indah, dan menjadikan Allah sebagai pelindung bukan berarti tidak memerlukan bantuan sesama karena Islam memerintahkan saling menolong dalam perkara yang dibenarkan.'},
{level:'HOTS',indicator:'Menentukan perilaku memuji Allah ketika tertimpa musibah',text:'Seorang pelajar kehilangan barang yang disayanginya. Perilaku yang paling tepat sebagai penghayatan terhadap Asmaul Husna al-Hamid adalah ...',options:['mengucapkan hamdalah dan doa musibah lalu mencari barang dengan sungguh','mengucapkan hamdalah karena kehilangan itu merupakan hal yang harus diterima','tidak mengucapkan apa pun karena mengucapkan hamdalah ketika kehilangan terasa tidak tulus','mengucapkan istighfar karena kehilangan merupakan akibat dosa yang telah dilakukan'],answer:0,explanation:'Hadis menyebut bahwa Rasulullah apabila memperoleh hal yang menyenangkan maka mengucapkan segala puji bagi Allah yang dengan nikmat-Nya sempurnalah kebaikan dan apabila memperoleh hal yang tidak menyenangkan maka mengucapkan segala puji bagi Allah dalam setiap keadaan. Hadis juga menyebut bahwa tidak ada seorang muslim yang tertimpa musibah lalu mengucapkan doa yang diajarkan yaitu innalillahi wa inna ilaihi rajiun allahumma ajirni fi musibati wa akhlif li khairan minha melainkan Allah memberi ganti dengan yang lebih baik. Q.S. al-Baqarah [2]: 155-157 menyebut ujian dengan kekurangan harta dan jiwa serta memberi kabar gembira kepada orang yang sabar. Hadis melarang ucapan seandainya ketika menghadapi kegagalan karena membuka perbuatan setan. Q.S. al-Hadid [57]: 22-23 menyebut bahwa tidak ada musibah yang menimpa di bumi dan pada diri sendiri melainkan telah tertulis dalam kitab sebelum Allah mewujudkannya agar manusia tidak bersedih atas apa yang luput dan tidak gembira atas apa yang diberikan. Adapun istighfar juga dianjurkan tetapi bukan pengganti hamdalah, dan kehilangan harta tidak selalu merupakan akibat dosa karena ujian juga menimpa orang saleh.'},
{level:'HOTS',indicator:'Menganalisis hikmah ditetapkannya nama asy-Syakur',text:'Allah membalas amal hamba dengan balasan yang berlipat walaupun amal itu sedikit dan menyebut diri-Nya asy-Syakur. Analisis yang paling tepat terhadap hikmah penetapan tersebut adalah ...',options:['hikmahnya agar hamba beramal sebanyak mungkin karena balasan ditentukan oleh jumlah amal','hikmahnya agar hamba mengetahui bahwa amal kecil lebih utama daripada amal besar karena balasannya berlipat','hamba terdorong beramal dan tidak sombong karena semua atas karunia','hikmahnya agar hamba tidak merasa berat beramal karena amalnya pasti diterima'],answer:2,explanation:'Q.S. al-Baqarah [2]: 261 memberi perumpamaan satu biji yang menumbuhkan tujuh tangkai dan pada setiap tangkai terdapat seratus biji serta menyebut bahwa Allah melipatgandakan bagi siapa yang dikehendaki-Nya dan Allah Maha Luas lagi Maha Mengetahui. Q.S. az-Zalzalah [99]: 7-8 menyebut bahwa kebaikan sebesar biji zarrah akan dilihat. Hadis qudsi menyebut bahwa barangsiapa datang dengan kebaikan maka baginya sepuluh kali lipatnya atau lebih, dan barangsiapa datang dengan keburukan maka balasan keburukan itu serupa atau diampuni. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis menyebut bahwa surga memiliki seratus tingkatan yang jarak antara dua tingkatan seperti jarak antara langit dan bumi, sehingga balasan tidak ditentukan oleh jumlah amal semata melainkan oleh keikhlasan dan karunia Allah. Hadis juga menganjurkan membalas kebaikan dengan kebaikan dan menyebut bahwa orang yang tidak berterima kasih kepada manusia tidak bersyukur kepada Allah. Adapun amal besar tetap lebih utama daripada amal kecil apabila keduanya dilakukan dengan ikhlas.'},
{level:'HOTS',indicator:'Menentukan perilaku yang mencerminkan penghayatan al-Aliyy dalam pergaulan',text:'Perilaku yang paling tepat sebagai penghayatan terhadap Asmaul Husna al-Aliyy dalam pergaulan adalah ...',options:['tidak merasa lebih tinggi dan menghormati orang yang memiliki keutamaan','tidak menghormati orang yang kedudukannya lebih rendah karena menghormati dapat menurunkan kedudukan sendiri','tidak menghormati siapa pun karena menghormati hanya layak diberikan kepada Allah','menuntut penghormatan dari orang lain karena penghormatan merupakan hak orang yang memiliki kedudukan'],answer:0,explanation:'Hadis menyebut bahwa tidak akan masuk surga orang yang di dalam hatinya terdapat kesombongan sebesar biji sawi dan bahwa sombong adalah menolak kebenaran dan meremehkan manusia. Hadis juga menyebut bahwa Allah mewahyukan agar bersikap tawadu sehingga tidak ada seorang pun yang menyombongkan diri atas yang lain dan tidak ada yang menzalimi yang lain. Hadis menyebut bahwa tidak ada yang bersikap tawadu karena Allah melainkan Allah mengangkat derajatnya. Hadis juga menyebut bahwa Rasulullah tidak menyukai orang berdiri untuk menghormatinya sebagaimana orang-orang bukan muslim melakukannya. Hadis menyebut bahwa tidak termasuk golongan Rasulullah orang yang tidak menghormati orang yang lebih tua dan tidak menyayangi yang lebih muda serta tidak mengetahui hak orang alim. Q.S. al-Hujurat [49]: 13 menegaskan bahwa yang paling mulia di sisi Allah adalah yang paling bertakwa. Q.S. al-Munafiqun [63]: 8 menyebut bahwa kemuliaan itu hanyalah bagi Allah, bagi Rasul-Nya, dan bagi orang-orang mukmin. Karena itu menghormati orang yang memiliki keutamaan merupakan adab sedangkan mengangkat makhluk ke kedudukan yang hanya layak bagi Allah merupakan bentuk berlebihan yang dilarang.'},
{level:'HOTS',indicator:'Menganalisis pengaruh penghayatan al-Waliy terhadap ketenangan jiwa',text:'Orang yang menghayati bahwa Allah merupakan al-Waliy tampak lebih tenang ketika menghadapi ancaman. Analisis yang paling tepat terhadap pengaruh tersebut adalah ...',options:['pengaruh itu terjadi karena ancaman yang dihadapi tidak benar-benar berbahaya bagi dirinya','keyakinan pada pelindung yang menguasai sebab menjadikan hati tidak gelisah','pengaruh itu terjadi karena orang tersebut telah terbiasa menghadapi ancaman sehingga tidak lagi merasa takut','pengaruh itu terjadi karena orang tersebut tidak menyadari besarnya ancaman yang dihadapi'],answer:1,explanation:'Q.S. at-Taubah [9]: 40 menceritakan Rasulullah yang berkata kepada sahabatnya ketika keduanya berada dalam gua janganlah bersedih hati sesungguhnya Allah bersama kita, sehingga Allah menurunkan ketenangan kepadanya dan memperkuatnya dengan bala tentara yang tidak terlihat. Q.S. Ali Imran [3]: 173 menceritakan orang beriman yang ketika dikatakan kepada mereka bahwa manusia telah berkumpul untuk menyerang mereka maka iman mereka bertambah dan mereka mengucapkan cukuplah Allah bagi kami dan Dia adalah sebaik-baik pelindung. Q.S. ar-Rad [13]: 28 menyebut bahwa hati menjadi tenteram dengan mengingat Allah. Hadis juga menyebut bahwa barangsiapa bertawakal kepada Allah maka Dia mencukupinya. Hadis menyebut bahwa ikatlah untamu lalu bertawakallah, yang menunjukkan bahwa usaha tetap merupakan bagian dari tawakal. Q.S. al-Maidah [5]: 23 menceritakan dua orang yang bertakwa yang berkata masuki pintu itu dengan menyerbu apabila kalian memasukinya niscaya kalian akan menang dan bertawakallah kepada Allah apabila kalian benar-benar orang beriman. Karena itu ketenangan itu lahir dari keyakinan terhadap kekuasaan pelindung bukan dari ketidaktahuan tentang besarnya ancaman.'},
{level:'HOTS',indicator:'Menentukan cara membalas kebaikan orang lain sebagai penghayatan asy-Syakur',text:'Cara membalas kebaikan orang lain yang paling tepat sebagai penghayatan terhadap Asmaul Husna asy-Syakur adalah ...',options:['membalas dengan pemberian yang lebih besar agar tidak merasa berhutang budi','membalas hanya apabila orang yang memberi kebaikan memerlukan bantuan pada suatu saat','membalas dengan kebaikan setara dan mendoakan kebaikan bagi pemberinya','tidak membalas karena membalas kebaikan merupakan kewajiban orang yang diberi'],answer:2,explanation:'Hadis menyebut bahwa barangsiapa diberi kebaikan oleh orang lain lalu berkata jazakallahu khairan maka ia telah berlebihan dalam memuji, sehingga doa merupakan balasan yang dianjurkan ketika tidak mampu membalas dengan harta. Hadis juga menyebut bahwa orang yang tidak bersyukur kepada manusia tidak bersyukur kepada Allah. Hadis menyebut bahwa Rasulullah menerima hadiah dan membalasnya, sehingga membalas dengan yang setara atau lebih baik merupakan sunah. Q.S. an-Nahl [16]: 126 menganjurkan membalas dengan balasan yang serupa dan menyebut bahwa bersabar lebih baik bagi orang yang sabar. Hadis juga melarang memuji secara berlebihan sehingga menyebut kebaikan orang lain harus dilakukan dengan cara yang benar. Q.S. al-Baqarah [2]: 264 melarang menghilangkan pahala pemberian dengan menyebut-nyebutnya, sehingga orang yang memberi tidak boleh menyebut pemberiannya dan orang yang diberi dianjurkan mengakui kebaikan itu. Adapun tidak membalas bukan penghayatan asy-Syakur karena Allah membalas kebaikan hamba sehingga hamba dianjurkan meneladani sifat itu, dan membalas hanya ketika diperlukan menunjukkan bahwa kebaikan orang lain diingat hanya ketika ada keperluan.'},
{level:'HOTS',indicator:'Menganalisis hikmah disebutnya al-Hamid bersama al-Waliy dalam satu ayat',text:'Q.S. asy-Syura [42]: 28 menggandengkan al-Waliy dengan al-Hamid dalam konteks turunnya hujan setelah manusia berputus asa. Analisis yang paling tepat terhadap hikmah penggandengan tersebut adalah ...',options:['hikmahnya agar manusia mengetahui bahwa hujan merupakan tanda kekuasaan Allah','perlindungan Allah selalu disertai pujian dalam ditahan atau diberi nikmat','hikmahnya agar manusia tidak berputus asa ketika hujan tidak turun dalam waktu yang lama','hikmahnya karena hujan merupakan nikmat yang paling besar sehingga perlu disebut bersama nama Allah yang paling agung'],answer:1,explanation:'Q.S. asy-Syura [42]: 28 berbunyi dan Dialah yang menurunkan hujan setelah mereka berputus asa dan menyebarkan rahmat-Nya dan Dialah Sang Pelindung lagi Maha Terpuji. Q.S. ar-Rum [30]: 48-49 menceritakan Allah yang mengirim angin lalu menggerakkan awan dan membentangkannya di langit sebagaimana dikehendaki-Nya dan menjadikannya bergumpal-gumpal lalu hujan terlihat keluar dari celahnya, dan apabila Dia menimpakan hujan itu kepada siapa yang dikehendaki-Nya dari hamba-hamba-Nya maka tiba-tiba mereka bergembira, dan sesungguhnya sebelum hujan diturunkan kepada mereka mereka benar-benar telah berputus asa. Q.S. Ibrahim [14]: 7 memerintahkan bersyukur dan menjanjikan tambahan nikmat. Hadis juga menyebut bahwa Rasulullah mengucapkan hamdalah dalam setiap keadaan baik yang menyenangkan maupun yang tidak menyenangkan. Q.S. al-Baqarah [2]: 186 menyebut bahwa Allah dekat dan mengabulkan doa orang yang berdoa. Hadis juga menyebut bahwa doa tidak ditolak melainkan diganti dengan yang serupa atau dihindarkan dari keburukan yang setara atau disimpan untuk di akhirat.'},
{level:'HOTS',indicator:'Menentukan perilaku menghindari ketergantungan pada makhluk sebagai penghayatan al-Waliy',text:'Perilaku yang paling tepat untuk menghindari ketergantungan pada makhluk sebagai penghayatan terhadap Asmaul Husna al-Waliy adalah ...',options:['tidak pernah menolak permintaan bantuan dari orang lain agar tidak dianggap bergantung pada makhluk','meminta bantuan sesuai kemampuan makhluk tanpa menggantungkan harapan hati','meminta bantuan hanya kepada orang yang dekat secara hubungan keluarga agar tidak berhutang budi kepada orang lain','tidak meminta bantuan kepada siapa pun karena meminta bantuan menunjukkan ketergantungan pada makhluk'],answer:1,explanation:'Hadis menyebut kisah Rasulullah yang membaiat sebagian sahabat agar tidak meminta sesuatu kepada manusia, sehingga seorang di antara mereka tidak meminta cambuknya kepada orang lain apabila jatuh dan turun sendiri mengambilnya, yang menunjukkan keutamaan tidak meminta kepada makhluk dalam perkara yang dapat dikerjakan sendiri. Hadis juga menyebut bahwa tangan yang di atas lebih baik daripada tangan yang di bawah dan mulailah dari orang yang menjadi tanggunganmu. Hadis menyebut bahwa Allah menolong hamba selama hamba menolong saudaranya, sehingga meminta bantuan dalam perkara yang menjadi kemampuan sesama merupakan hal yang dibolehkan. Hadis juga menganjurkan tidak meminta kepada manusia dengan cara yang memaksa dan menyebut bahwa orang yang meminta kepada manusia untuk menumpuk harta maka ia meminta bara api. Q.S. al-Fatihah [1]: 5 mengajarkan ibadah hanya kepada Allah dan memohon pertolongan hanya kepada-Nya. Adapun tidak pernah menolak permintaan bantuan bukan penghayatan al-Waliy karena menolak permintaan yang tidak mampu dipenuhi atau yang dilarang merupakan hal yang dibenarkan.'},
{level:'HOTS',indicator:'Menganalisis kedudukan memuji Allah dalam seluruh keadaan',text:'Rasulullah mengucapkan hamdalah baik ketika memperoleh hal yang menyenangkan maupun ketika memperoleh hal yang tidak menyenangkan. Analisis yang paling tepat terhadap kedudukan memuji Allah dalam seluruh keadaan adalah ...',options:['kedudukan itu menunjukkan bahwa keadaan yang tidak menyenangkan tidak perlu disesali karena merupakan ketentuan Allah','memuji dalam keadaan sulit merupakan tingkatan pujian yang lebih tinggi','kedudukan itu menunjukkan bahwa memuji Allah merupakan kewajiban dalam setiap keadaan sehingga tidak memuji merupakan dosa','kedudukan itu menunjukkan bahwa pujian dalam keadaan sulit lebih utama daripada pujian dalam keadaan senang sehingga keadaan sulit perlu dicari'],answer:1,explanation:'Hadis menyebut bahwa Rasulullah apabila memperoleh hal yang menyenangkan maka mengucapkan segala puji bagi Allah yang dengan nikmat-Nya sempurnalah kebaikan dan apabila memperoleh hal yang tidak menyenangkan maka mengucapkan segala puji bagi Allah dalam setiap keadaan. Q.S. al-Baqarah [2]: 216 menyebut bahwa boleh jadi manusia membenci sesuatu padahal sesuatu itu baik bagi mereka dan boleh jadi menyukai sesuatu padahal sesuatu itu buruk bagi mereka, sedangkan Allah mengetahui dan manusia tidak mengetahui. Q.S. al-Kahfi [18]: 65-82 menceritakan kisah Nabi Musa bersama hamba yang saleh yang menunjukkan bahwa ketentuan yang tampak buruk mengandung hikmah yang tidak segera diketahui. Hadis juga menyebut bahwa perkara orang mukmin seluruhnya merupakan kebaikan yaitu apabila memperoleh kesenangan maka bersyukur dan itu baik baginya, dan apabila tertimpa kesulitan maka bersabar dan itu baik baginya. Q.S. az-Zumar [39]: 10 menyebut bahwa orang yang bersabar memperoleh pahala tanpa hisab. Adapun keadaan yang tidak menyenangkan tetap boleh disesali secara wajar karena Rasulullah juga bersedih ketika putranya wafat, tetapi kesedihan itu tidak disertai kata yang menunjukkan keberatan terhadap ketentuan Allah.'},
{level:'HOTS',indicator:'Menentukan cara meneladani sifat asy-Syakur dalam kehidupan sekolah',text:'Cara meneladani sifat asy-Syakur dalam kehidupan sekolah yang paling tepat adalah ...',options:['memberi imbalan kepada teman yang membantu mengerjakan tugas agar tidak berhutang budi','menghargai bantuan teman dan membalas kebaikan guru serta teman','membalas kebaikan teman hanya apabila teman itu membalas kebaikan kita terlebih dahulu','tidak menerima bantuan dari teman agar tidak perlu membalas kebaikannya'],answer:1,explanation:'Hadis menyebut bahwa orang yang tidak bersyukur kepada manusia tidak bersyukur kepada Allah. Hadis juga menyebut bahwa barangsiapa diberi kebaikan oleh orang lain lalu berkata jazakallahu khairan maka ia telah berlebihan dalam memuji, sehingga ucapan terima kasih dan doa merupakan bentuk membalas yang dianjurkan. Hadis menyebut bahwa sebaik-baik manusia adalah yang paling bermanfaat bagi manusia. Hadis juga menyebut bahwa Rasulullah menerima hadiah dan membalasnya. Hadis lain menyebut bahwa bentuk bakti setelah orang tua wafat termasuk memuliakan sahabat keduanya, yang menunjukkan bahwa jasa orang yang telah berbuat baik tidak dilupakan setelah berlalu waktu. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga menghargai bantuan yang kecil merupakan bagian dari penghayatan. Adapun tidak menerima bantuan agar tidak perlu membalas bukan cara yang tepat karena saling membantu merupakan bagian dari kehidupan bermasyarakat yang dianjurkan.'},
{level:'HOTS',indicator:'Menganalisis hikmah dilarangnya menyebut diri sendiri suci dalam kaitannya dengan al-Hamid',text:'Allah merupakan al-Hamid yaitu Zat yang terpuji, sedangkan manusia dilarang menyebut dirinya sendiri suci. Analisis yang paling tepat terhadap hikmah larangan tersebut adalah ...',options:['larangan itu karena menyebut diri sendiri suci merupakan bentuk kedustaan','larangan itu berarti manusia tidak boleh mengetahui kelebihannya sendiri','pujian hakiki hanya bagi Allah sehingga menyebut diri suci dilarang','larangan itu hanya berlaku apabila menyebut diri sendiri suci dilakukan di depan orang lain'],answer:2,explanation:'Q.S. an-Najm [53]: 32 berbunyi maka janganlah kamu mengatakan dirimu suci karena Dialah yang paling mengetahui tentang orang yang bertakwa. Q.S. al-Hujurat [49]: 14 menggambarkan orang Arab Badui yang berkata kami telah beriman lalu dijawab katakanlah kalian belum beriman tetapi katakanlah kami telah tunduk karena iman belum masuk ke dalam hati kalian, yang menunjukkan bahwa pengakuan atas keadaan batin sendiri tidak diterima tanpa bukti. Hadis menyebut bahwa apabila seorang sahabat memuji sahabat lain di hadapan Rasulullah maka beliau bersabda celakalah engkau, engkau telah memutus leher sahabatmu, dan mengajarkan agar mengatakan aku mengiranya demikian dan Allah yang menghitungnya serta tidak ada seorang pun yang dapat menyucikan seseorang di hadapan Allah. Hadis qudsi juga menyebut bahwa kebesaran merupakan selendang Allah sehingga mengambil pujian untuk diri sendiri merupakan bentuk menyaingi hak Allah. Q.S. al-Fatihah [1]: 2 menyebut segala puji bagi Allah Tuhan seluruh alam. Adapun mengetahui kelebihan diri sendiri dibolehkan sebagai sarana bersyukur selama tidak disertai perasaan lebih tinggi dari orang lain.'},
{level:'HOTS',indicator:'Menentukan perilaku menghindari takut kepada makhluk sebagai penghayatan al-Aliyy',text:'Perilaku yang paling tepat untuk menghindari rasa takut yang berlebihan kepada makhluk sebagai penghayatan terhadap Asmaul Husna al-Aliyy adalah ...',options:['tidak mengambil tindakan pencegahan terhadap bahaya karena pencegahan menunjukkan ketakutan kepada makhluk','tidak takut kehilangan keyakinan karena makhluk tidak berkuasa sendiri','menyampaikan kebenaran tanpa mempertimbangkan cara karena menyampaikan kebenaran merupakan kewajiban yang tidak memerlukan pertimbangan','tidak takut kepada siapa pun karena takut hanya layak diberikan kepada Allah'],answer:1,explanation:'Q.S. Ali Imran [3]: 175 menyebut bahwa janganlah kalian takut kepada mereka tetapi takutlah kepada-Ku apabila kalian benar-benar orang beriman. Q.S. at-Taubah [9]: 13 menyebut perintah memerangi pemimpin kekufuran dan menyebut apakah kalian takut kepada mereka padahal Allah lebih berhak untuk kalian takuti apabila kalian benar-benar orang beriman. Q.S. al-Maidah [5]: 44 menyebut larangan takut kepada manusia dalam menyampaikan hukum Allah. Hadis juga menyebut bahwa barangsiapa mencari ridha Allah walaupun manusia marah maka Allah mencukupkannya dari urusan manusia. Q.S. al-Baqarah [2]: 195 melarang menjatuhkan diri ke dalam kebinasaan, sehingga mengambil tindakan pencegahan terhadap bahaya yang nyata merupakan perintah agama bukan bentuk ketakutan yang tercela. Q.S. an-Nahl [16]: 125 memerintahkan menyeru dengan hikmah dan nasihat yang baik serta berdebat dengan cara yang terbaik, sehingga mempertimbangkan cara menyampaikan merupakan bagian dari hikmah bukan bentuk ketakutan.'},
{level:'HOTS',indicator:'Menganalisis hubungan al-Waliy dengan tawakal',text:'Menjadikan Allah sebagai al-Waliy berkaitan erat dengan tawakal. Analisis yang paling tepat terhadap hubungan tersebut adalah ...',options:['hubungan itu berarti tawakal hanya diperlukan ketika menghadapi persoalan yang tidak dapat diselesaikan','tawakal merupakan wujud nyata dari menjadikan Allah sebagai pelindung','hubungan itu menunjukkan bahwa tawakal berarti menyerahkan seluruh urusan kepada Allah tanpa berusaha','hubungan itu menunjukkan bahwa menjadikan Allah sebagai pelindung tidak memerlukan tawakal karena perlindungan Allah diberikan kepada seluruh orang beriman'],answer:1,explanation:'Hadis menyebut kisah seorang sahabat yang bertanya apakah untanya diikat lalu bertawakal atau dibiarkan lalu bertawakal, lalu Rasulullah bersabda ikatlah untamu lalu bertawakallah. Q.S. al-Maidah [5]: 23 menyebut perintah bertawakal kepada Allah apabila benar-benar beriman. Q.S. Ali Imran [3]: 159 memerintahkan bermusyawarah dalam urusan kemudian apabila telah membulatkan tekad maka bertawakallah kepada Allah, yang menunjukkan bahwa tawakal datang setelah perencanaan dan musyawarah. Q.S. at-Talaq [65]: 3 menyebut bahwa barangsiapa bertawakal kepada Allah maka Dia mencukupinya dan Allah menyampaikan urusan yang dikehendaki-Nya. Q.S. al-Anfal [8]: 2 menggambarkan orang beriman yang hatinya bergetar ketika disebut nama Allah dan yang bertawakal kepada Tuhannya. Q.S. al-Baqarah [2]: 257 menyebut Allah sebagai pelindung orang beriman. Hadis juga menyebut bahwa orang yang bertawakal kepada Allah dengan sebenar-benar tawakal akan diberi rezeki sebagaimana burung yang pergi pada pagi hari dalam keadaan lapar dan kembali pada sore hari dalam keadaan kenyang, yang menunjukkan bahwa burung itu tetap pergi berusaha.'},
{level:'HOTS',indicator:'Menentukan perilaku memuji kebaikan orang lain tanpa berlebihan',text:'Perilaku yang paling tepat dalam memuji kebaikan orang lain tanpa berlebihan adalah ...',options:['tidak memuji orang lain sama sekali karena memuji dapat menimbulkan kesombongan','memuji kebaikan yang tampak dengan benar dan tidak melebih-lebihkan','memuji seluruh kebaikan orang lain agar ia termotivasi melakukan kebaikan yang lebih banyak','memuji orang lain dengan sebutan yang tinggi agar ia merasa dihargai dan terus berbuat baik'],answer:1,explanation:'Hadis menyebut bahwa Rasulullah bersabda kepada orang yang memuji sahabat di hadapannya celakalah engkau, engkau telah memutus leher sahabatmu, dan apabila orang yang dipuji mendengar maka ia akan binasa, lalu mengajarkan agar mengatakan aku mengiranya demikian dan Allah yang menghitungnya serta tidak ada seorang pun yang dapat menyucikan seseorang di hadapan Allah. Hadis juga melarang memuji secara berlebihan dan menyebut bahwa melempar tanah ke wajah orang yang memuji berlebihan merupakan sikap yang dianjurkan. Hadis lain melarang berlebihan dalam memuji Rasulullah sebagaimana orang Nasrani berlebihan dalam memuji Isa bin Maryam dan bersabda aku hanyalah seorang hamba maka katakanlah hamba Allah dan rasul-Nya. Q.S. an-Najm [53]: 32 melarang menyebut diri sendiri suci karena Allah paling mengetahui tentang orang yang bertakwa. Hadis menyebut bahwa orang yang tidak bersyukur kepada manusia tidak bersyukur kepada Allah, sehingga memuji kebaikan yang tampak dengan cara yang benar merupakan bagian dari syukur. Hadis juga menganjurkan mendoakan kebaikan bagi saudara tanpa kehadirannya karena doa itu mustajab.'},
{level:'HOTS',indicator:'Menganalisis hikmah dianjurkannya berdoa dengan Asmaul Husna',text:'Q.S. al-Araf [7]: 180 menyebut bahwa Allah memiliki Asmaul Husna maka bermohonlah kepada-Nya dengan menyebut Asmaul Husna itu. Analisis yang paling tepat terhadap hikmah anjuran tersebut adalah ...',options:['doa disesuaikan dengan nama yang berkaitan dengan permohonannya','hikmahnya karena menyebut Asmaul Husna merupakan syarat sah doa sehingga tanpa menyebutnya doa tidak diterima','hikmahnya agar doa tidak dikabulkan sebelum seluruh Asmaul Husna disebutkan','hikmahnya agar doa menjadi lebih panjang sehingga lebih mungkin dikabulkan'],answer:0,explanation:'Q.S. al-Araf [7]: 180 berbunyi dan milik Allah Asmaul Husna maka bermohonlah kepada-Nya dengan menyebut Asmaul Husna itu dan tinggalkanlah orang-orang yang menyimpang dari kebenaran dalam menyebut nama-nama-Nya, kelak mereka akan mendapat balasan atas apa yang telah mereka kerjakan. Q.S. al-Isra [17]: 110 memerintahkan menyeru Allah atau menyeru ar-Rahman karena nama mana pun yang diseru maka milik-Nya nama-nama yang terbaik dan memerintahkan tidak mengeraskan suara dalam salat serta tidak merendahkannya melainkan mencari jalan tengah. Hadis menyebut bahwa Allah memiliki sembilan puluh sembilan nama yaitu seratus kurang satu dan barangsiapa menghafalnya maka masuk surga. Hadis juga menyebut kisah sahabat yang berdoa dengan menyebut nama-nama Allah dalam salatnya lalu Rasulullah bersabda ia berdoa dengan nama yang apabila digunakan berdoa maka dikabulkan dan apabila digunakan memohon maka diberi. Q.S. al-Baqarah [2]: 186 menyebut bahwa Allah dekat dan mengabulkan doa orang yang berdoa. Adapun menyebut seluruh Asmaul Husna bukan keharusan dan menyebut nama bukan syarat sah doa karena doa dengan bahasa sendiri juga diterima selama isinya tidak dilarang.'},
{level:'HOTS',indicator:'Menentukan cara menghafal dan mengamalkan Asmaul Husna',text:'Cara menghafal dan mengamalkan Asmaul Husna yang paling tepat adalah ...',options:['menghafal bertahap, memahami makna, dan menyebutnya dalam doa','mengamalkan Asmaul Husna dengan menyebutnya sebanyak mungkin dalam satu waktu agar memperoleh pahala yang besar','menghafal nama-nama itu tanpa memahami maknanya karena menghafal sudah memperoleh pahala','menghafal seluruh Asmaul Husna dalam waktu singkat lalu mengamalkannya secara bersamaan'],answer:0,explanation:'Hadis menyebut bahwa Allah memiliki sembilan puluh sembilan nama dan barangsiapa menghafalnya maka masuk surga, dan para ulama menjelaskan bahwa menghafal dalam hadis itu mencakup menghafal lafalnya, memahami maknanya, dan beramal dengan kandungan maknanya. Q.S. al-Araf [7]: 180 memerintahkan bermohon kepada Allah dengan menyebut Asmaul Husna. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga menghafal secara bertahap dan mengamalkannya secara berkelanjutan lebih utama daripada menghafal banyak dalam waktu singkat lalu berhenti. Hadis menyebut bahwa Allah Maha Indah dan menyukai keindahan. Q.S. Muhammad [47]: 19 memerintahkan mengetahui bahwa tidak ada tuhan melainkan Allah dan memohonkan ampunan, sehingga mengetahui makna merupakan dasar amal. Adapun menghafal tanpa memahami tetap memperoleh pahala hafalan tetapi tidak menghasilkan penghayatan yang mengubah perilaku, dan menyebut nama sebanyak mungkin dalam satu waktu bukan cara yang diajarkan karena zikir yang utama adalah yang disertai pemahaman dan berkelanjutan.'},
{level:'HOTS',indicator:'Menganalisis pengaruh penghayatan keempat Asmaul Husna terhadap akhlak',text:'Seseorang yang menghayati al-Waliy, al-Hamid, asy-Syakur, dan al-Aliyy tampak lebih tenang, lebih bersyukur, dan lebih rendah hati. Analisis yang paling tepat terhadap pengaruh tersebut adalah ...',options:['pengaruh itu terjadi karena penghayatan Asmaul Husna merupakan ibadah yang paling utama sehingga menghasilkan seluruh kebaikan','pengaruh itu terjadi karena penghayatan Asmaul Husna menghasilkan pengetahuan tentang sifat Allah','penghayatan mengubah cara pandang terhadap diri dan terhadap Tuhannya','pengaruh itu hanya tampak pada orang yang menghafal seluruh Asmaul Husna bukan pada yang menghafal sebagian'],answer:2,explanation:'Hadis menyebut bahwa dalam tubuh terdapat segumpal daging yang apabila baik maka baiklah seluruh tubuh dan apabila rusak maka rusaklah seluruh tubuh yaitu hati, yang menunjukkan bahwa keyakinan yang tertanam dalam hati menghasilkan perilaku. Hadis juga menyebut bahwa Allah memiliki sembilan puluh sembilan nama dan barangsiapa menghafalnya maka masuk surga, dan para ulama menjelaskan bahwa menghafal mencakup memahami dan mengamalkan kandungan maknanya. Q.S. ar-Rad [13]: 28 menyebut bahwa hati menjadi tenteram dengan mengingat Allah. Q.S. Ibrahim [14]: 7 menyebut bahwa apabila bersyukur maka Allah menambah nikmat. Hadis qudsi menyebut bahwa kebesaran merupakan selendang Allah sehingga menyadari ketinggian Allah menghasilkan kerendahan hati. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Q.S. al-Ahzab [33]: 21 menyebut bahwa pada diri Rasulullah terdapat teladan yang baik. Adapun penghayatan sebagian nama tetap menghasilkan pengaruh sesuai kadar penghayatannya sehingga tidak terbatas pada yang menghafal seluruhnya.'},
{level:'HOTS',indicator:'Menentukan perilaku ketika ditolong oleh orang lain sebagai penghayatan al-Waliy',text:'Seorang pelajar tertolong oleh orang yang tidak dikenalnya ketika mengalami kesulitan di jalan. Perilaku yang paling tepat sebagai penghayatan terhadap Asmaul Husna al-Waliy adalah ...',options:['berterima kasih dan meyakini Allah sebagai sumber pertolongan hakiki','membalas kebaikan orang itu dengan pemberian yang lebih besar agar tidak merasa berhutang budi','mencari orang itu untuk membalas kebaikannya walaupun memerlukan waktu dan biaya yang besar','tidak menerima pertolongan dari orang yang tidak dikenal agar tidak berhutang budi kepada siapa pun'],answer:0,explanation:'Hadis menyebut bahwa orang yang tidak bersyukur kepada manusia tidak bersyukur kepada Allah, sehingga berterima kasih kepada orang yang menolong merupakan bagian dari syukur. Hadis juga menyebut bahwa barangsiapa diberi kebaikan oleh orang lain lalu berkata jazakallahu khairan maka ia telah berlebihan dalam memuji, sehingga doa merupakan balasan yang dianjurkan ketika tidak mampu membalas dengan harta. Hadis menyebut bahwa Allah menolong hamba selama hamba menolong saudaranya, sehingga meneruskan kebaikan kepada orang lain merupakan wujud syukur. Q.S. at-Taubah [9]: 51 mengajarkan ucapan cukuplah Allah bagi kami dan Dia adalah sebaik-baik pelindung. Hadis juga menyebut kisah Rasulullah yang membaiat sebagian sahabat agar tidak meminta sesuatu kepada manusia, yang menunjukkan keutamaan tidak menggantungkan diri pada makhluk. Hadis menyebut bahwa tangan yang di atas lebih baik daripada tangan yang di bawah. Adapun mencari orang itu dengan mengeluarkan biaya besar untuk membalas bukan keharusan karena doa sudah merupakan balasan yang cukup, dan menolak pertolongan dari orang yang tidak dikenal bukan adab karena saling menolong merupakan bagian dari kehidupan bermasyarakat.'},
{level:'HOTS',indicator:'Menganalisis hikmah disebutnya al-Hamid dalam Q.S. al-Fatihah',text:'Setiap rakaat salat diawali dengan Q.S. al-Fatihah yang dibuka dengan segala puji bagi Allah. Analisis yang paling tepat terhadap hikmah pembukaan tersebut dalam kaitannya dengan al-Hamid adalah ...',options:['hikmahnya karena pujian merupakan syarat sah salat sehingga tanpa membaca al-Fatihah salat tidak sah','mengawali ibadah dengan pujian sebelum menyampaikan permohonan','hikmahnya agar Q.S. al-Fatihah menjadi surah yang paling sering dibaca oleh umat Islam','hikmahnya agar orang yang salat memulai ibadahnya dengan bacaan yang mudah dihafal'],answer:1,explanation:'Hadis menyebut bahwa tidak sah salat seseorang yang tidak membaca Ummul Quran yaitu al-Fatihah, sehingga membaca al-Fatihah merupakan rukun salat bukan sekadar pembukaan yang mudah dihafal. Hadis juga menyebut kisah Rasulullah yang mendengar seseorang berdoa dalam salatnya tanpa memuji Allah dan tanpa bersalawat kepada Nabi lalu bersabda orang itu tergesa-gesa, kemudian mengajarkan agar memuji Allah dengan pujian yang layak bagi-Nya, bersalawat kepada Nabi, lalu berdoa dengan apa yang dikehendaki. Q.S. al-Araf [7]: 180 memerintahkan bermohon kepada Allah dengan menyebut Asmaul Husna. Q.S. al-Hijr [15]: 87 menyebut bahwa Allah memberikan kepada Rasulullah tujuh ayat yang dibaca berulang-ulang dan Al-Quran yang agung. Hadis juga menyebut bahwa kalimat yang paling dicintai Allah ada empat yaitu subhanallah, alhamdulillah, la ilaha illallah, dan Allahu akbar. Q.S. al-Isra [17]: 110 menyebut bahwa milik Allah nama-nama yang terbaik. Adapun pujian bukan syarat sah salat karena syarat sah berkaitan dengan suci dari hadas dan najis, menutup aurat, menghadap kiblat, dan masuknya waktu.'},
{level:'HOTS',indicator:'Menentukan perilaku beramal kecil secara berkelanjutan sebagai penghayatan asy-Syakur',text:'Perilaku yang paling tepat sebagai penghayatan terhadap Asmaul Husna asy-Syakur dalam beramal adalah ...',options:['menetapkan amal kecil harian dan menjaganya secara berkelanjutan','menunda amal kecil hingga mampu melaksanakan amal besar karena amal kecil dianggap kurang bernilai','melaksanakan amal sebanyak mungkin dalam satu hari lalu berhenti karena lelah sehingga tidak mampu melanjutkan','melaksanakan amal besar sekali dalam setahun agar pahalanya setara dengan amal kecil yang berkelanjutan'],answer:0,explanation:'Hadis menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis juga menyebut bahwa Rasulullah apabila mengerjakan suatu amal maka menetapkannya, dan apabila meninggalkannya karena sakit atau tidur maka menggantinya pada waktu lain. Hadis menyebut bahwa Rasulullah bersabda beramallah sesuai kemampuan kalian karena Allah tidak jemu sehingga kalian jemu. Hadis juga melarang membebani diri dengan amal yang tidak mampu dilanjutkan dan menyebut kisah tali pengikat di masjid yang diperintahkan untuk dilepas karena pemiliknya menggunakannya ketika letih dalam salat. Q.S. al-Kahfi [18]: 110 memerintahkan beramal saleh dan tidak mempersekutukan seorang pun dalam beribadah kepada Tuhan. Hadis juga menyebut bahwa janganlah meremehkan kebaikan sedikit pun walaupun hanya bertemu saudaramu dengan wajah yang berseri. Q.S. az-Zalzalah [99]: 7-8 menyebut bahwa kebaikan sebesar biji zarrah akan dilihat. Adapun melaksanakan amal sebanyak mungkin lalu berhenti bukan cara yang dianjurkan karena keberlanjutan lebih utama daripada jumlah, dan menunda amal kecil hingga mampu beramal besar sering berakibat amal tidak terlaksana sama sekali.'},
{level:'HOTS',indicator:'Menganalisis kedudukan ketinggian makhluk dalam kaitannya dengan al-Aliyy',text:'Manusia memperoleh kedudukan, harta, dan ilmu yang menjadikannya lebih tinggi dari manusia lain. Analisis yang paling tepat terhadap kedudukan ketinggian tersebut dalam kaitannya dengan Asmaul Husna al-Aliyy adalah ...',options:['kedudukan ketinggian itu tidak bernilai di sisi Allah sehingga tidak perlu diusahakan','kedudukan ketinggian itu merupakan tanda kemuliaan di sisi Allah sehingga layak dibanggakan','kedudukan ketinggian itu merupakan hasil usaha pribadi sehingga menjadi hak milik yang tidak perlu dipertanggungjawabkan','ketinggian makhluk merupakan amanah dan ujian bukan tanda kemuliaan'],answer:3,explanation:'Q.S. az-Zukhruf [43]: 32 menyebut bahwa Allah membagi rezeki di antara manusia dan meninggikan sebagian atas sebagian yang lain dalam derajat agar sebagian dapat memanfaatkan sebagian yang lain, dan rahmat Tuhan lebih baik dari apa yang mereka kumpulkan. Q.S. al-Hujurat [49]: 13 menegaskan bahwa yang paling mulia di sisi Allah adalah yang paling bertakwa. Hadis menyebut bahwa Allah tidak melihat kepada rupa dan harta kalian melainkan kepada hati dan amal kalian. Hadis juga menyebut bahwa setiap kalian adalah pemimpin dan akan dimintai pertanggungjawaban tentang yang dipimpinnya. Hadis menyebut bahwa sombong adalah menolak kebenaran dan meremehkan manusia dan bahwa tidak akan masuk surga orang yang di dalam hatinya terdapat kesombongan sebesar biji sawi. Hadis qudsi menyebut bahwa kebesaran merupakan selendang Allah dan keperkasaan merupakan pakaian-Nya. Q.S. al-Munafiqun [63]: 8 menyebut bahwa kemuliaan itu hanyalah bagi Allah, bagi Rasul-Nya, dan bagi orang-orang mukmin. Hadis juga menyebut bahwa tidak ada yang bersikap tawadu karena Allah melainkan Allah mengangkat derajatnya.'},
{level:'HOTS',indicator:'Menentukan perilaku ketika memperoleh kedudukan sebagai penghayatan al-Aliyy',text:'Seorang pelajar terpilih menjadi ketua dalam suatu organisasi di sekolah. Perilaku yang paling tepat sebagai penghayatan terhadap Asmaul Husna al-Aliyy adalah ...',options:['menerima kedudukan sebagai amanah dan tidak menuntut penghormatan khusus','menolak kedudukan itu agar tidak perlu bertanggung jawab atas kesalahan anggota','menolak kedudukan itu karena kedudukan selalu menimbulkan kesombongan','menerima kedudukan itu lalu menuntut anggota menghormati kedudukannya agar organisasi teratur'],answer:0,explanation:'Hadis menyebut bahwa setiap kalian adalah pemimpin dan akan dimintai pertanggungjawaban tentang yang dipimpinnya. Hadis juga menyebut bahwa Rasulullah tidak menyukai orang berdiri untuk menghormatinya sebagaimana orang-orang bukan muslim melakukannya. Hadis menyebut bahwa sebaik-baik manusia adalah yang paling bermanfaat bagi manusia. Hadis juga menyebut bahwa tidak ada yang bersikap tawadu karena Allah melainkan Allah mengangkat derajatnya. Hadis menyebut bahwa apabila seseorang memberikan suatu amanah kepada orang lain maka amanah itu tidak boleh dikhianati. Q.S. al-Hujurat [49]: 13 menegaskan bahwa yang paling mulia di sisi Allah adalah yang paling bertakwa. Hadis juga menyebut bahwa Allah tidak melihat kepada rupa dan harta kalian melainkan kepada hati dan amal kalian. Adapun menolak kedudukan karena takut sombong bukan penyelesaian yang tepat apabila ia mampu menjalankan amanah itu dan memberikan manfaat, karena meninggalkan kesempatan memberi manfaat juga merupakan kerugian, dan ketakutan terhadap sombong dapat diatasi dengan kesadaran bahwa kedudukan merupakan amanah yang disertai tanggung jawab.'},
{level:'HOTS',indicator:'Menganalisis hikmah dijadikannya pujian sebagai pembuka zikir yang utama',text:'Kalimat alhamdulillah merupakan kalimat yang paling dicintai Allah bersama tiga kalimat lain. Analisis yang paling tepat terhadap hikmah dijadikannya pujian sebagai bagian dari zikir yang utama adalah ...',options:['pujian merupakan pengakuan paling ringkas atas kesempurnaan Allah','hikmahnya agar umat Islam terbiasa mengucapkan kalimat itu sehingga menjadi ciri khas','hikmahnya karena kalimat itu lebih mudah dihafal oleh anak-anak daripada kalimat zikir lain','hikmahnya agar kalimat itu diucapkan sebanyak mungkin tanpa perlu memahami maknanya'],answer:0,explanation:'Hadis menyebut bahwa kalimat yang paling dicintai Allah ada empat yaitu subhanallah, alhamdulillah, la ilaha illallah, dan Allahu akbar, dan tidak mengapa dengan yang mana pun engkau mulai. Hadis juga menyebut bahwa ucapan yang paling utama setelah Al-Quran ada empat dan tidak mengapa dengan yang mana pun dimulai. Hadis menyebut bahwa Rasulullah mengucapkan hamdalah dalam setiap keadaan baik yang menyenangkan maupun yang tidak menyenangkan. Q.S. al-Fatihah [1]: 2 menyebut segala puji bagi Allah Tuhan seluruh alam. Q.S. az-Zumar [39]: 7 menyebut bahwa apabila bersyukur maka syukur itu untuk diri sendiri. Hadis juga menyebut bahwa orang yang tidak bersyukur kepada manusia tidak bersyukur kepada Allah. Hadis menganjurkan memahami makna zikir yang diucapkan dan menyebut bahwa zikir yang disertai kehadiran hati lebih utama. Adapun mengucapkan kalimat itu tanpa memahami maknanya tetap memperoleh pahala tetapi tidak menghasilkan pengaruh terhadap akhlak, dan kemudahan menghafal bukan hikmah utama dari dijadikannya pujian sebagai zikir yang dicintai.'},
{level:'HOTS',indicator:'Menentukan perilaku ketika amal yang dikerjakan tidak dihargai oleh orang lain',text:'Seorang pelajar mengerjakan tugas kelompok dengan sungguh-sungguh tetapi hasilnya diakui oleh teman lain. Perilaku yang paling tepat sebagai penghayatan terhadap Asmaul Husna asy-Syakur dan al-Hamid adalah ...',options:['menyampaikan kebenaran secara sopan dan tetap beramal sungguh-sungguh','menyampaikan kepada seluruh anggota kelas bahwa ia yang mengerjakan tugas itu agar haknya kembali','tidak mengerjakan tugas pada kesempatan berikutnya agar teman itu merasakan akibat perbuatannya','menceritakan perbuatan teman itu kepada seluruh teman agar mereka mengetahui bahwa teman itu tidak jujur'],answer:0,explanation:'Q.S. az-Zalzalah [99]: 7 menyebut bahwa barangsiapa mengerjakan kebaikan sebesar biji zarrah maka ia akan melihatnya, sehingga amal yang tidak dihargai oleh manusia tetap memperoleh balasan dari Allah. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis menyebut bahwa cukuplah seseorang dianggap berdusta apabila menyampaikan setiap yang didengarnya, sehingga menceritakan perbuatan orang lain kepada banyak orang tanpa keperluan yang sah dapat menjadi bentuk ghibah. Q.S. an-Nisa [4]: 135 memerintahkan menjadi saksi karena Allah walaupun terhadap diri sendiri dan kerabat, sehingga menyampaikan kebenaran kepada pihak yang berwenang dengan cara yang sopan merupakan kewajiban. Hadis juga menyebut bahwa barangsiapa menipu maka ia bukan dari golongan Rasulullah. Q.S. al-Hujurat [49]: 6 memerintahkan meneliti kebenaran berita sebelum bertindak atasnya. Hadis menganjurkan menolak kejahatan dengan cara yang lebih baik sebagaimana Q.S. Fushshilat [41]: 34. Adapun berhenti mengerjakan tugas merugikan diri sendiri dan tidak memperbaiki keadaan, dan menyampaikan kepada seluruh anggota kelas dengan maksud mempermalukan bukan cara yang diajarkan.'},
{level:'HOTS',indicator:'Menganalisis pengaruh penghayatan al-Waliy terhadap sikap dalam menghadapi kegagalan',text:'Seseorang yang menghayati bahwa Allah merupakan al-Waliy tidak berputus asa ketika usahanya gagal. Analisis yang paling tepat terhadap pengaruh tersebut adalah ...',options:['pengaruh itu terjadi karena ia tidak memahami sebab kegagalannya sehingga tidak merasa kecewa','pengaruh itu terjadi karena ia yakin bahwa kegagalan tidak akan terjadi lagi di masa depan','kegagalan dipandang bagian pengaturan yang mengandung hikmah','pengaruh itu terjadi karena ia telah terbiasa gagal sehingga kegagalan tidak lagi mempengaruhi perasaannya'],answer:2,explanation:'Q.S. at-Talaq [65]: 2-3 menyebut bahwa barangsiapa bertakwa kepada Allah maka Dia mengadakan baginya jalan keluar dan memberi rezeki dari arah yang tidak disangka, dan barangsiapa bertawakal kepada Allah maka Dia mencukupinya. Q.S. al-Insyirah [94]: 5-6 menyebut bahwa bersama kesulitan terdapat kemudahan. Hadis melarang ucapan seandainya ketika menghadapi kegagalan dan menyebut bahwa ucapan itu membuka perbuatan setan, lalu mengajarkan agar mengatakan bahwa apa yang Allah kehendaki terjadi dan apa yang tidak dikehendaki-Nya tidak terjadi. Q.S. Yusuf [12]: 87 melarang berputus asa dari rahmat Allah dan menyebut bahwa tidak ada yang berputus asa dari rahmat Allah kecuali kaum yang kafir. Q.S. al-Baqarah [2]: 216 menyebut bahwa boleh jadi manusia membenci sesuatu padahal sesuatu itu baik bagi mereka. Hadis juga menyebut bahwa pertolongan itu bersama kesabaran dan bahwa kelapangan itu bersama kesempitan. Q.S. al-Baqarah [2]: 186 menyebut bahwa Allah dekat dan mengabulkan doa orang yang berdoa. Adapun tidak memahami sebab kegagalan justru menghalangi perbaikan, dan terbiasa gagal bukan penghayatan melainkan kepasrahan yang tidak disertai usaha.'},
{level:'HOTS',indicator:'Menentukan perilaku memuji Allah melalui perbuatan sebagai penghayatan al-Hamid',text:'Perilaku memuji Allah melalui perbuatan yang paling tepat sebagai penghayatan terhadap Asmaul Husna al-Hamid adalah ...',options:['melaksanakan ibadah sunah sebanyak mungkin dan mengabaikan ibadah wajib karena ibadah sunah merupakan wujud pujian yang lebih nyata','melaksanakan ibadah yang banyak agar pujian kepada Allah tampak nyata dalam jumlah ibadah','menyampaikan kepada orang lain seluruh nikmat yang diterima agar mereka mengetahui bahwa Allah telah memuliakannya','menggunakan nikmat sesuai tujuan pemberiannya dan menjauhi kemaksiatan'],answer:3,explanation:'Hadis menyebut bahwa Allah menyukai apabila hamba-Nya menggunakan nikmat yang diberikan untuk ketaatan dan tidak menggunakannya untuk kemaksiatan. Q.S. Ibrahim [14]: 7 menyebut bahwa apabila bersyukur maka Allah menambah nikmat dan apabila mengingkari maka azab Allah sangat pedih. Hadis juga menyebut bahwa pada hari kiamat seorang hamba ditanya tentang empat hal di antaranya tentang ilmunya apa yang diamalkannya dan tentang hartanya dari mana diperoleh dan ke mana dibelanjakan. Q.S. al-Baqarah [2]: 159 menyebut bahwa orang yang menyembunyikan apa yang telah diturunkan berupa keterangan dan petunjuk dilaknat. Hadis menyebut bahwa tidak sah salat tanpa bersuci dan tidak diterima sedekah dari harta yang diperoleh secara curang, sehingga menunaikan hak berkaitan dengan harta merupakan wujud syukur. Q.S. al-Hadid [57]: 7 memerintahkan menafkahkan sebagian dari apa yang Allah jadikan manusia berkuasa atasnya. Adapun menyampaikan seluruh nikmat kepada orang lain dengan maksud memperlihatkan kemuliaan diri bukan pujian yang benar karena dapat tergolong riya dan menyebut-nyebut nikmat dengan cara yang menimbulkan iri pada orang lain.'},
{level:'HOTS',indicator:'Menganalisis hikmah disebutnya asy-Syakur bersama janji tambahan karunia',text:'Q.S. Fathir [35]: 30 menyebut bahwa Allah akan menyempurnakan pahala dan menambah karunia bagi orang yang beriman dan beramal saleh serta menyebut diri-Nya Maha Pengampun lagi Maha Mensyukuri. Analisis yang paling tepat terhadap hikmah penggandengan tersebut adalah ...',options:['hikmahnya agar orang beriman tidak perlu memperhatikan kesalahan karena kesalahan akan diampuni','hikmahnya agar orang beriman mengetahui bahwa pahalanya akan disempurnakan','ampunan dan balasan sempurna menjadikan hamba tidak berputus asa','hikmahnya karena penambahan karunia merupakan hak orang beriman sehingga dapat dituntut dari Allah'],answer:2,explanation:'Q.S. Fathir [35]: 29-30 berbunyi sesungguhnya orang-orang yang selalu membaca kitab Allah dan mendirikan salat dan menafkahkan sebagian dari rezeki yang Kami anugerahkan kepada mereka dengan diam-diam dan terang-terangan mereka mengharapkan perniagaan yang tidak akan merugi, agar Allah menyempurnakan kepada mereka pahala mereka dan menambah kepada mereka dari karunia-Nya, sesungguhnya Allah Maha Pengampun lagi Maha Mensyukuri. Q.S. asy-Syura [42]: 23 menyebut kabar gembira bagi orang yang beriman dan beramal saleh bahwa Allah menambah karunia-Nya. Hadis qudsi menyebut bahwa barangsiapa datang dengan kebaikan maka baginya sepuluh kali lipatnya atau lebih, dan barangsiapa datang dengan keburukan maka balasan keburukan itu serupa atau diampuni. Q.S. az-Zumar [39]: 53 melarang berputus asa dari rahmat Allah dan menyebut bahwa Allah mengampuni seluruh dosa. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Q.S. al-Araf [7]: 56 memerintahkan berdoa dengan rasa takut dan harap. Adapun penambahan karunia merupakan karunia Allah bukan hak yang dapat dituntut, dan tidak memperhatikan kesalahan bukan ajaran Islam karena taubat merupakan kewajiban.'},
{level:'HOTS',indicator:'Menentukan perilaku ketika melihat orang lain memperoleh kedudukan tinggi',text:'Perilaku yang paling tepat ketika melihat orang lain memperoleh kedudukan yang tinggi sebagai penghayatan terhadap Asmaul Husna al-Aliyy adalah ...',options:['tidak merasa iri karena kedudukan dunia tidak bernilai di sisi Allah','mengharapkan kedudukan serupa agar dapat memperoleh manfaat yang sama','menjauhi orang yang memperoleh kedudukan itu agar tidak tergoda untuk mengharapkan kedudukan serupa','tidak iri dan meyakini ketinggian hakiki ditentukan oleh ketakwaan'],answer:3,explanation:'Hadis menyebut bahwa tidak boleh ada hasad kecuali dalam dua hal yang para ulama jelaskan sebagai ghibthah yaitu keinginan memperoleh nikmat serupa tanpa berharap nikmat itu hilang dari pemiliknya, sehingga mengharapkan kedudukan serupa untuk memberi manfaat merupakan ghibthah yang dibolehkan apabila disertai niat yang benar. Hadis juga menyebut bahwa jauhilah hasad karena hasad memakan kebaikan sebagaimana api memakan kayu bakar. Q.S. al-Hujurat [49]: 13 menegaskan bahwa yang paling mulia di sisi Allah adalah yang paling bertakwa. Hadis juga menyebut bahwa tidak ada ketaatan kepada makhluk dalam bermaksiat kepada Pencipta, sehingga menghormati orang yang berkuasa tidak berarti tunduk pada perintahnya yang salah. Hadis menganjurkan mendoakan kebaikan bagi pemimpin agar mereka memperoleh petunjuk dan keadilan. Q.S. an-Nisa [4]: 32 melarang mengangan-angankan kelebihan yang diberikan Allah kepada sebagian orang atas sebagian yang lain dan memerintahkan memohon karunia Allah. Adapun menjauhi orang yang memperoleh kedudukan bukan cara yang tepat karena menghilangkan kesempatan berbuat baik dan memberi nasihat.'},
{level:'HOTS',indicator:'Menganalisis kedudukan Asmaul Husna sebagai sarana mengenal Allah',text:'Asmaul Husna dipelajari agar hamba mengenal Tuhannya. Analisis yang paling tepat terhadap kedudukan Asmaul Husna sebagai sarana mengenal Allah adalah ...',options:['kedudukan itu menunjukkan bahwa Asmaul Husna merupakan satu-satunya cara memperoleh pahala yang besar','kedudukan itu menunjukkan bahwa mengenal Allah hanya dapat dilakukan melalui Asmaul Husna','kedudukan itu menunjukkan bahwa mengenal Allah melalui Asmaul Husna hanya dapat dilakukan oleh orang yang berilmu tinggi','Asmaul Husna menjadi sarana utama mengenal Allah melalui nama-Nya'],answer:3,explanation:'Q.S. al-Araf [7]: 180 menyebut bahwa milik Allah Asmaul Husna maka bermohonlah kepada-Nya dengan menyebut Asmaul Husna itu. Q.S. al-Hasyr [59]: 24 menyebut bahwa milik Allah Asmaul Husna dan bertasbihlah kepada-Nya segala yang di langit dan di bumi. Hadis menyebut bahwa Allah memiliki sembilan puluh sembilan nama dan barangsiapa menghafalnya maka masuk surga, dan para ulama menjelaskan bahwa menghafal mencakup memahami makna dan mengamalkan kandungan maknanya. Q.S. Muhammad [47]: 19 memerintahkan mengetahui bahwa tidak ada tuhan melainkan Allah. Hadis juga menyebut bahwa orang yang paling utama di antara manusia adalah mukmin yang berjihad di jalan Allah dengan jiwa dan hartanya kemudian mukmin yang menyendiri di lembah untuk beribadah kepada Tuhannya, sehingga pengenalan Allah menghasilkan amal. Q.S. al-Baqarah [2]: 186 menyebut bahwa Allah dekat dan mengabulkan doa orang yang berdoa. Adapun mengenal Allah tidak terbatas pada Asmaul Husna karena dapat juga melalui ciptaan-Nya dan melalui kitab-Nya, dan Asmaul Husna dapat dipahami oleh setiap orang sesuai dengan tingkat kemampuannya.'},
{level:'HOTS',indicator:'Menentukan cara mengajarkan Asmaul Husna kepada teman sebaya',text:'Cara mengajarkan Asmaul Husna kepada teman sebaya yang paling tepat adalah ...',options:['menyampaikan nama-nama itu dalam bentuk hafalan yang harus diulang setiap hari agar teman cepat hafal','memulai dari nama yang sering dipakai dan menjelaskan dengan contoh sederhana','menyampaikan seluruh nama yang dihafalnya agar teman mengetahui luasnya pengetahuannya','tidak mengajarkan kepada teman karena mengajarkan merupakan tugas guru dan orang tua'],answer:1,explanation:'Q.S. an-Nahl [16]: 125 memerintahkan menyeru kepada jalan Tuhan dengan hikmah, nasihat yang baik, dan berdebat dengan cara yang terbaik. Hadis menyebut bahwa barangsiapa menunjukkan kepada kebaikan maka ia memperoleh pahala seperti pahala orang yang mengerjakannya. Hadis juga menyebut bahwa sampaikanlah dariku walaupun satu ayat. Hadis menyebut bahwa tidaklah kelembutan ada pada sesuatu melainkan ia menghiasinya. Hadis juga menganjurkan meringankan dalam mengajar dan menyebut bahwa mudahkanlah dan jangan mempersulit serta sampaikanlah kabar gembira dan jangan membuat orang menjauh. Hadis menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga mengajarkan secara bertahap lebih utama daripada menyampaikan banyak sekaligus. Hadis juga menyebut bahwa seorang mukmin merupakan cermin bagi saudaranya. Adapun tidak mengajarkan kepada teman bukan pilihan yang tepat karena menyampaikan ilmu merupakan kewajiban bagi yang mengetahuinya dalam kadar kemampuannya.'},
{level:'HOTS',indicator:'Menganalisis hubungan al-Hamid dengan syukur atas nikmat yang tidak disadari',text:'Banyak nikmat Allah yang tidak disadari oleh manusia seperti kesehatan dan keamanan. Analisis yang paling tepat terhadap hubungan kenyataan tersebut dengan penghayatan al-Hamid adalah ...',options:['hubungan itu menunjukkan bahwa manusia harus menghitung seluruh nikmat agar syukurnya sah','pujian tidak dibatasi pada nikmat yang disadari oleh manusia saja','hubungan itu menunjukkan bahwa nikmat yang tidak disadari tidak perlu disyukuri karena tidak diketahui','hubungan itu menunjukkan bahwa nikmat yang tidak disadari bukan merupakan nikmat yang sebenarnya'],answer:1,explanation:'Q.S. an-Nahl [16]: 18 menyebut bahwa apabila menghitung nikmat Allah niscaya tidak mampu menghitungnya, sesungguhnya manusia benar-benar zalim lagi mengingkari. Q.S. an-Nahl [16]: 53 menyebut bahwa apa pun nikmat yang ada pada manusia maka dari Allah dan apabila ditimpa kemudaratan maka hanya kepada-Nya mereka meminta pertolongan. Hadis memerintahkan memandang orang yang lebih rendah dalam urusan dunia agar tidak meremehkan nikmat Allah. Hadis juga menyebut bahwa Rasulullah mengucapkan hamdalah dalam setiap keadaan. Q.S. Ibrahim [14]: 34 menyebut bahwa Allah memberikan kepada manusia segala apa yang diminta kepada-Nya dan apabila menghitung nikmat Allah niscaya tidak mampu menghitungnya. Hadis menyebut bahwa dua nikmat yang banyak manusia tertipu di dalamnya yaitu kesehatan dan waktu luang, yang menunjukkan bahwa nikmat yang tidak disadari merupakan nikmat yang besar. Q.S. al-Baqarah [2]: 152 memerintahkan bersyukur dan melarang mengingkari nikmat. Adapun menghitung seluruh nikmat bukan syarat sah syukur karena tidak mungkin dilakukan, dan nikmat yang tidak disadari tetap merupakan nikmat yang sebenarnya karena keberadaannya tidak bergantung pada kesadaran manusia.'},
{level:'HOTS',indicator:'Menentukan perilaku menjaga keberlanjutan amal ketika semangat menurun',text:'Perilaku yang paling tepat untuk menjaga keberlanjutan amal ketika semangat menurun sebagai penghayatan terhadap Asmaul Husna asy-Syakur adalah ...',options:['berhenti beramal hingga semangat kembali agar amal yang dikerjakan terasa ikhlas','mengganti amal yang biasa dilakukan dengan amal lain yang lebih ringan agar terasa lebih mudah','mengurangi kadar amal tetapi tidak meninggalkannya sama sekali','tetap melaksanakan amal dengan kadar yang sama walaupun sangat letih karena berhenti beramal merupakan tanda berkurangnya iman'],answer:2,explanation:'Hadis menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis juga menyebut bahwa Rasulullah bersabda beramallah sesuai kemampuan kalian karena Allah tidak jemu sehingga kalian jemu. Hadis menyebut kisah tali pengikat di masjid yang diperintahkan untuk dilepas karena pemiliknya menggunakannya ketika letih dalam salat, lalu Rasulullah bersabda beramallah sesuai kemampuan. Hadis juga menyebut bahwa Rasulullah apabila meninggalkan amal karena sakit atau tidur maka menggantinya pada waktu lain, sehingga mengurangi kadar bukan berarti meninggalkan. Q.S. al-Baqarah [2]: 286 menegaskan bahwa Allah tidak membebani seseorang melainkan sesuai kesanggupannya. Hadis qudsi menyebut bahwa Allah berfirman Aku sesuai dengan prasangka hamba-Ku terhadap-Ku. Hadis juga menyebut bahwa hati manusia berada di antara dua jari dari jari-jari ar-Rahman yang Dia bolak-balikkan sesuai kehendak-Nya, sehingga memohon keteguhan hati merupakan doa yang dianjurkan. Hadis lain menganjurkan berdoa dengan menyebut nama-nama Allah yang berkaitan dengan permohonan.'},
{level:'HOTS',indicator:'Menganalisis hikmah dilarang menjadikan pelindung selain Allah',text:'Allah melarang menjadikan pelindung selain-Nya dan menyebut bahwa orang yang melakukannya berada dalam pengawasan-Nya. Analisis yang paling tepat terhadap hikmah larangan tersebut adalah ...',options:['hikmahnya agar manusia tidak memerlukan bantuan siapa pun sehingga mandiri dalam seluruh keadaan','hikmahnya karena pelindung selain Allah selalu menzalimi orang yang berlindung kepadanya','pelindung selain Allah merusak tauhid dan menimbulkan kekecewaan','hikmahnya agar manusia tidak berhubungan dengan pihak yang berkuasa'],answer:2,explanation:'Q.S. asy-Syura [42]: 9 menyebut bahwa orang yang menjadikan pelindung selain Allah maka Allah merupakan pengawas atas seluruh perbuatan mereka dan engkau bukan pemberi peringatan atas mereka. Q.S. al-Ankabut [29]: 41 memberi perumpamaan orang yang menjadikan pelindung selain Allah seperti laba-laba yang membuat rumah dan sesungguhnya rumah yang paling rapuh adalah rumah laba-laba. Q.S. al-Jatsiyah [45]: 19 menyebut bahwa mereka tidak akan berguna sedikit pun bagi manusia terhadap azab Allah. Q.S. Yunus [10]: 49 menyebut bahwa Rasulullah tidak berkuasa menarik manfaat bagi dirinya dan tidak pula menolak mudarat kecuali apa yang Allah kehendaki. Hadis juga menyebut bahwa barangsiapa menggantungkan sesuatu maka ia diserahkan kepada sesuatu itu. Q.S. al-Kahfi [18]: 110 memerintahkan beramal saleh dan tidak mempersekutukan seorang pun dalam beribadah kepada Tuhan. Hadis juga menganjurkan tidak meminta sesuatu kepada manusia dan menyebut kisah sahabat yang turun sendiri mengambil cambuknya yang jatuh. Adapun larangan itu bukan berarti tidak boleh berhubungan dengan pihak yang berkuasa dalam urusan yang dibenarkan, dan bukan berarti tidak memerlukan bantuan sesama karena Islam memerintahkan saling menolong dalam kebaikan.'},
{level:'HOTS',indicator:'Menentukan perilaku ketika doa belum dikabulkan sebagai penghayatan al-Waliy',text:'Seorang pelajar telah berdoa memohon keberhasilan tetapi permohonannya belum dikabulkan. Perilaku yang paling tepat sebagai penghayatan terhadap Asmaul Husna al-Waliy adalah ...',options:['berhenti berdoa karena doanya tidak dikabulkan sehingga berdoa lagi tidak bermanfaat','mengurangi ibadah karena ibadahnya tidak menghasilkan permohonan yang dikabulkan','berdoa dengan cara yang lebih memaksa agar permohonannya segera dikabulkan','tidak berhenti berdoa dan tidak berprasangka buruk kepada Allah'],answer:3,explanation:'Hadis menyebut bahwa doa setiap hamba dikabulkan selama tidak berdoa untuk dosa atau untuk memutus silaturahmi dan tidak tergesa-gesa, dan ketika ditanya apa maksud tergesa-gesa beliau menjawab mengatakan aku telah berdoa tetapi belum dikabulkan lalu merasa putus asa dan meninggalkan doa. Hadis juga menyebut bahwa doa tidak ditolak melainkan diganti dengan yang serupa atau dihindarkan dari keburukan yang setara atau disimpan untuknya di akhirat. Hadis menggambarkan musafir yang berdoa sambil mengangkat tangan tetapi makanan, minuman, dan pakaiannya haram sehingga bagaimana mungkin doanya dikabulkan, yang menunjukkan bahwa harta yang tidak halal merupakan penghalang. Q.S. al-Baqarah [2]: 186 menyebut bahwa Allah dekat dan mengabulkan doa orang yang berdoa apabila ia berdoa kepada-Nya. Hadis menyebut bahwa ikatlah untamu lalu bertawakallah, sehingga usaha tetap merupakan bagian dari tawakal. Q.S. al-Baqarah [2]: 216 menyebut bahwa boleh jadi manusia membenci sesuatu padahal sesuatu itu baik bagi mereka. Adapun berdoa dengan cara yang memaksa bukan adab karena Q.S. al-Araf [7]: 55 melarang berdoa dengan melampaui batas.'},
{level:'HOTS',indicator:'Menganalisis hikmah digabungkannya penghayatan keempat Asmaul Husna dalam akhlak',text:'Penghayatan al-Waliy, al-Hamid, asy-Syakur, dan al-Aliyy menghasilkan akhlak yang seimbang pada diri seorang pelajar. Analisis yang paling tepat terhadap hikmah penggabungan keempatnya adalah ...',options:['hikmahnya agar pelajar menghafal keempat nama itu sebagai bagian dari hafalan Asmaul Husna','keempat nama menutup empat kelemahan utama dalam diri manusia','hikmahnya agar pelajar memperoleh pengetahuan yang lengkap tentang Asmaul Husna','hikmahnya karena keempat nama itu merupakan nama yang paling mudah dipahami oleh pelajar sehingga dipilih sebagai bahan pelajaran'],answer:1,explanation:'Q.S. al-Baqarah [2]: 257 menyebut bahwa Allah adalah pelindung orang-orang yang beriman yang mengeluarkan mereka dari kegelapan kepada cahaya. Q.S. asy-Syura [42]: 28 menyebut Dialah Sang Pelindung lagi Maha Terpuji. Q.S. Fathir [35]: 30 menyebut bahwa Allah Maha Pengampun lagi Maha Mensyukuri dalam konteks menyempurnakan pahala. Q.S. Luqman [31]: 30 menyebut bahwa Allah Maha Tinggi lagi Maha Besar. Hadis qudsi menyebut bahwa kebesaran merupakan selendang Allah dan keperkasaan merupakan pakaian-Nya sehingga barangsiapa menyaingi-Nya akan dimasukkan ke neraka. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Hadis menyebut bahwa Rasulullah mengucapkan hamdalah dalam setiap keadaan. Hadis juga menyebut bahwa dalam tubuh terdapat segumpal daging yang apabila baik maka baiklah seluruh tubuh yaitu hati. Q.S. ar-Rad [13]: 28 menyebut bahwa hati menjadi tenteram dengan mengingat Allah. Karena itu keempat nama itu menghasilkan keseimbangan akhlak yang menutup kelemahan utama manusia.'},
{level:'HOTS',indicator:'Menentukan perilaku menghormati guru sebagai penghayatan al-Aliyy dan al-Waliy',text:'Perilaku yang paling tepat sebagai penghayatan terhadap Asmaul Husna al-Aliyy dan al-Waliy dalam menghormati guru adalah ...',options:['menghormati guru karena ilmunya tanpa mengangkatnya seperti kedudukan Allah','menghormati guru dengan cara menuruti seluruh keinginannya agar memperoleh keberkahan dari ilmunya','menghormati guru karena guru memiliki kedudukan yang tinggi sehingga wajib ditaati dalam seluruh perkara','tidak menghormati guru secara berlebihan karena berlebihan dalam menghormati dapat menimbulkan kesyirikan'],answer:0,explanation:'Q.S. az-Zukhruf [43]: 32 menyebut bahwa Allah meninggikan sebagian atas sebagian yang lain dalam derajat agar sebagian dapat memanfaatkan sebagian yang lain, sehingga kedudukan guru merupakan bagian dari pengaturan Allah. Hadis menyebut bahwa tidak termasuk golongan Rasulullah orang yang tidak menghormati orang yang lebih tua dan tidak menyayangi yang lebih muda serta tidak mengetahui hak orang alim. Hadis juga menyebut bahwa tidak ada ketaatan kepada makhluk dalam bermaksiat kepada Pencipta, sehingga ketaatan kepada guru berlaku dalam perkara yang baik. Hadis melarang berlebihan dalam memuji dan menyebut kisah Rasulullah yang bersabda janganlah kalian berlebih-lebihan dalam memujiku sebagaimana orang Nasrani berlebihan dalam memuji Isa bin Maryam karena aku hanyalah seorang hamba maka katakanlah hamba Allah dan rasul-Nya. Hadis juga menyebut bahwa bentuk bakti setelah orang tua wafat termasuk memuliakan sahabat keduanya, sehingga menyambung hubungan dengan guru merupakan bagian dari adab terhadap ilmu. Q.S. al-Mujadilah [58]: 11 menyebut bahwa Allah mengangkat derajat orang yang diberi ilmu beberapa derajat.'}
]});
